const ParsedGlobalQueryTable = struct {
    parsed: std.json.Parsed(metadata_openapi.GlobalStatefulQueryRequest),
    table_name: []const u8,

    pub fn deinit(self: *@This()) void {
        self.parsed.deinit();
    }
};

const RaftQuarantineView = struct {
    group_id: u64,
    incident_id: u64,
    reason: raft_mod.host.QuarantineReason,
    observed_bytes: usize,
    configured_limit_at_detection: usize,
    current_limit_bytes: usize,
    max_recovery_bytes: usize,
    first_observed_round: u64,
    last_observed_round: u64,
    occurrences: u64,
    can_resume: bool,
    suggested_action: []const u8,

    fn fromStatus(status: raft_mod.host.GroupQuarantineStatus) RaftQuarantineView {
        const quarantine = status.quarantine;
        return .{
            .group_id = status.group_id,
            .incident_id = quarantine.incident_id,
            .reason = quarantine.reason,
            .observed_bytes = quarantine.observed_bytes,
            .configured_limit_at_detection = quarantine.configured_limit,
            .current_limit_bytes = status.current_limit,
            .max_recovery_bytes = status.max_recovery_bytes,
            .first_observed_round = quarantine.first_observed_round,
            .last_observed_round = quarantine.last_observed_round,
            .occurrences = quarantine.occurrences,
            .can_resume = status.can_resume,
            .suggested_action = if (status.can_resume)
                "resume with the current incident_id"
            else
                "authorize a one-shot recovery allowance of at least observed_bytes for the current incident_id",
        };
    }
};

const ResumeRaftQuarantineRequest = struct {
    expected_incident_id: u64,
    new_limit_bytes: ?u64 = null,
};

fn parseGlobalQueryTable(alloc: std.mem.Allocator, body: []const u8) !ParsedGlobalQueryTable {
    try query_contract.validatePublicQuerySortTupleContract(alloc, body);
    var parsed = metadata_server_openapi.server.parseGlobalQueryBody(alloc, body) catch return error.InvalidQueryRequest;
    errdefer parsed.deinit();
    const table_name = parsed.value.table orelse return error.InvalidQueryRequest;
    if (table_name.len == 0) return error.InvalidQueryRequest;
    return .{
        .parsed = parsed,
        .table_name = table_name,
    };
}

fn parseSchemaEtag(raw: []const u8) !u32 {
    const value = std.mem.trim(u8, raw, " \t\r\n");
    if (std.mem.startsWith(u8, value, "W/")) return error.WeakSchemaEtag;
    if (value.len < 10 or value[0] != '"' or value[value.len - 1] != '"')
        return error.InvalidSchemaEtag;
    const tag = value[1 .. value.len - 1];
    const prefix = "schema-";
    if (!std.mem.startsWith(u8, tag, prefix) or tag.len == prefix.len)
        return error.InvalidSchemaEtag;
    return try std.fmt.parseUnsigned(u32, tag[prefix.len..], 10);
}

fn setSchemaEtag(ctx: *httpx.Context, version: u32) !void {
    var buf: [32]u8 = undefined;
    const value = try std.fmt.bufPrint(&buf, "\"schema-{d}\"", .{version});
    try ctx.setHeader("ETag", value);
}

fn isNdjsonContentType(content_type: ?[]const u8) bool {
    const value = content_type orelse return false;
    const media_type = std.mem.trim(u8, if (std.mem.indexOfScalar(u8, value, ';')) |idx| value[0..idx] else value, " \t");
    return std.ascii.eqlIgnoreCase(media_type, "application/x-ndjson");
}

const DecodedRequestBody = struct {
    body: []u8,
    allocation: []u8,

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        alloc.free(self.allocation);
        self.* = undefined;
    }
};

fn gunzipRequestBodyAlloc(ctx: ?*httpx.Context, alloc: std.mem.Allocator, encoded: []const u8, max_size: usize) !DecodedRequestBody {
    var encoded_reader: std.Io.Reader = .fixed(encoded);
    var window: [std.compress.flate.max_window_len]u8 = undefined;
    var decompressor = std.compress.flate.Decompress.init(&encoded_reader, .gzip, &window);
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer {
        if (ctx) |request_ctx| request_ctx.releaseRequestBodyBuffer(out.capacity);
        out.deinit(alloc);
    }
    var buf: [16 * 1024]u8 = undefined;
    while (true) {
        const count = decompressor.reader.readSliceShort(&buf) catch |err| {
            if (err == error.EndOfStream) break;
            return error.InvalidCompressedBody;
        };
        if (count == 0) break;
        if (count > max_size -| out.items.len) return error.RequestBodyTooLarge;
        const required = out.items.len + count;
        if (required > out.capacity) {
            const geometric = out.capacity +| @max(out.capacity / 2, @as(usize, 16 * 1024));
            const new_capacity = @min(max_size, @max(required, geometric));
            const growth = new_capacity - out.capacity;
            if (ctx) |request_ctx| {
                if (!request_ctx.tryReserveRequestBodyBuffer(growth)) return error.BodyCapacityExceeded;
            }
            out.ensureTotalCapacityPrecise(alloc, new_capacity) catch |err| {
                if (ctx) |request_ctx| request_ctx.releaseRequestBodyBuffer(growth);
                return err;
            };
        }
        out.appendSliceAssumeCapacity(buf[0..count]);
    }
    const body = out.items;
    const allocation = out.allocatedSlice();
    out = .empty;
    return .{ .body = body, .allocation = allocation };
}

test "SQL DDL receipt status distinguishes unknown admission" {
    try std.testing.expectEqual(@as(u16, 200), AntflyApiHandler.sqlDdlReceiptHttpStatus(.ready));
    try std.testing.expectEqual(@as(u16, 202), AntflyApiHandler.sqlDdlReceiptHttpStatus(.pending));
    try std.testing.expectEqual(@as(u16, 409), AntflyApiHandler.sqlDdlReceiptHttpStatus(.invalid));
    try std.testing.expectEqual(@as(u16, 409), AntflyApiHandler.sqlDdlReceiptHttpStatus(.admission_unknown));
}

test "initial foreign-key create distinguishes unknown admission from accepted work" {
    const base: http_server_mod.ApiHttpServer.FkInitialCreateBegin = .{
        .plan_id = @splat(0),
        .catalog_id = 1,
        .child_table_id = 2,
        .state = .pending,
    };
    try std.testing.expectEqual(@as(u16, 202), AntflyApiHandler.fkInitialCreateHttpStatus(base));
    var uncertain = base;
    uncertain.state = .admission_unknown;
    try std.testing.expectEqual(@as(u16, 409), AntflyApiHandler.fkInitialCreateHttpStatus(uncertain));
}

test "gzip request bodies are decoded with an expanded-size limit" {
    const encoded = [_]u8{ 31, 139, 8, 0, 0, 0, 0, 0, 2, 255, 171, 174, 5, 0, 67, 191, 166, 163, 2, 0, 0, 0 };
    var decoded = try gunzipRequestBodyAlloc(null, std.testing.allocator, &encoded, 2);
    defer decoded.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("{}", decoded.body);
    try std.testing.expectError(error.RequestBodyTooLarge, gunzipRequestBodyAlloc(null, std.testing.allocator, &encoded, 1));
    try std.testing.expectError(error.InvalidCompressedBody, gunzipRequestBodyAlloc(null, std.testing.allocator, "not gzip", 1024));
}

test "gzip request bodies reserve expanded capacity from the shared server budget" {
    const encoded = [_]u8{ 31, 139, 8, 0, 0, 0, 0, 0, 2, 255, 171, 174, 5, 0, 67, 191, 166, 163, 2, 0, 0, 0 };
    var budget = httpx.SharedBodyBudget.init(1);
    var request = try httpx.Request.init(std.testing.allocator, .POST, "/");
    defer request.deinit();
    request.body_budget = &budget;
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);
    defer ctx.deinit();

    try std.testing.expectError(
        error.BodyCapacityExceeded,
        gunzipRequestBodyAlloc(&ctx, std.testing.allocator, &encoded, 2),
    );
    try std.testing.expectEqual(@as(usize, 0), budget.stats().in_use);
    try std.testing.expectEqual(@as(u64, 1), budget.stats().rejected_total);
}

test "invalid gzip releases partially expanded body capacity" {
    const encoded = [_]u8{ 31, 139, 8, 0, 0, 0, 0, 0, 2, 255, 171, 174, 5, 0, 67, 191, 166, 163, 2, 0, 0, 0 };
    var budget = httpx.SharedBodyBudget.init(32 * 1024);
    var request = try httpx.Request.init(std.testing.allocator, .POST, "/");
    defer request.deinit();
    request.body_budget = &budget;
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);
    defer ctx.deinit();

    try std.testing.expectError(
        error.InvalidCompressedBody,
        gunzipRequestBodyAlloc(&ctx, std.testing.allocator, encoded[0 .. encoded.len - 4], 1024),
    );
    try std.testing.expectEqual(@as(usize, 0), budget.stats().in_use);
}

test "gzip request body reservation follows the owned decoded buffer lifetime" {
    const encoded = [_]u8{ 31, 139, 8, 0, 0, 0, 0, 0, 2, 255, 171, 174, 5, 0, 67, 191, 166, 163, 2, 0, 0, 0 };
    var budget = httpx.SharedBodyBudget.init(32 * 1024);
    var request = try httpx.Request.init(std.testing.allocator, .POST, "/");
    request.body_budget = &budget;
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);

    const decoded = try gunzipRequestBodyAlloc(&ctx, std.testing.allocator, &encoded, 2);
    try request.replaceOwnedBodyAllocation(decoded.body, decoded.allocation);
    try std.testing.expectEqual(@as(usize, 2), budget.stats().in_use);

    ctx.deinit();
    request.deinit();
    try std.testing.expectEqual(@as(usize, 0), budget.stats().in_use);
}

test "gzip request completes with combined encoded and decoded budget" {
    const encoded = [_]u8{ 31, 139, 8, 0, 0, 0, 0, 0, 2, 255, 171, 174, 5, 0, 67, 191, 166, 163, 2, 0, 0, 0 };
    var budget = httpx.SharedBodyBudget.init(encoded.len + 2);
    try std.testing.expect(budget.tryReserve(encoded.len));

    var request = try httpx.Request.init(std.testing.allocator, .POST, "/");
    request.body_budget = &budget;
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);

    const decoded = try gunzipRequestBodyAlloc(&ctx, std.testing.allocator, &encoded, 2);
    try request.replaceOwnedBodyAllocation(decoded.body, decoded.allocation);
    try std.testing.expectEqual(encoded.len + 2, budget.stats().in_use);

    ctx.deinit();
    request.deinit();
    try std.testing.expectEqual(encoded.len, budget.stats().in_use);
    budget.release(encoded.len);
    try std.testing.expectEqual(@as(usize, 0), budget.stats().in_use);
}

fn requiresInternalServicePrincipal(path: []const u8) bool {
    const in_internal_namespace = std.mem.eql(u8, path, internal_routes.base) or
        std.mem.startsWith(u8, path, internal_routes.base ++ "/");
    // Hot-standby replication authenticates with its own bearer token; the
    // legacy `/internal/v1/ha` spelling stays exempt for one minor release.
    const standby_exempt = std.mem.eql(u8, path, internal_routes.standby) or
        std.mem.startsWith(u8, path, internal_routes.standby ++ "/") or
        std.mem.eql(u8, path, internal_routes.legacy_standby) or
        std.mem.startsWith(u8, path, internal_routes.legacy_standby ++ "/");
    return in_internal_namespace and !standby_exempt;
}

test "internal namespace requires a service principal except hot standby" {
    try std.testing.expect(requiresInternalServicePrincipal("/internal/v1"));
    try std.testing.expect(requiresInternalServicePrincipal("/internal/v1/capabilities"));
    try std.testing.expect(requiresInternalServicePrincipal("/internal/v1/future-operation"));
    try std.testing.expect(!requiresInternalServicePrincipal("/internal/v1/standby"));
    try std.testing.expect(!requiresInternalServicePrincipal("/internal/v1/standby/replication/start"));
    try std.testing.expect(!requiresInternalServicePrincipal("/internal/v1/ha"));
    try std.testing.expect(!requiresInternalServicePrincipal("/internal/v1/ha/replication/start"));
    try std.testing.expect(!requiresInternalServicePrincipal("/tables/internal/v1"));
}

fn storedDestinationAllowed(identity: ?AuthenticatedIdentity, table_name: []const u8) !bool {
    const authenticated = identity orelse return true;
    if (!std.mem.startsWith(u8, authenticated.credential_principal, "basic:") and
        !std.mem.startsWith(u8, authenticated.credential_principal, "api-key:"))
        return error.StoredDestinationCredentialUnsupported;
    return http_server_mod.permissionsAllow(authenticated.permissions, .table, table_name, .write);
}

fn witnessDDLError(ctx: *httpx.Context, err: anyerror) !httpx.Response {
    const jsonErrorResponse = AntflyApiHandler.jsonErrorResponse;
    return switch (err) {
        error.UnsupportedExternalLakeSchemaType => jsonErrorResponse(ctx, 400, "automatic lake schema detection requires supported flat scalar columns; unsupported nested or binary types need a compatible source"),
        error.ExternalLakeSchemaMismatch => jsonErrorResponse(ctx, 409, "lake files have incompatible column types or the supplied schema fingerprint does not match the detected schema"),
        error.ExternalLakeSchemaUnavailable => jsonErrorResponse(ctx, 400, "lake schema metadata is unavailable; Parquet inference requires at least one file with a schema"),
        error.ExternalLakeSchemaTooLarge => jsonErrorResponse(ctx, 400, "detected lake schema exceeds the 1024-column limit"),
        error.ReservedForeignKeySupportIndex => jsonErrorResponse(ctx, 400, "__fk_partial_ indexes are server-owned foreign-key support; edit or retire the foreign key instead"),
        error.ForeignKeyPartialSupportIndexConflict => jsonErrorResponse(ctx, 409, "foreign-key support index name conflicts with an existing definition"),
        error.ForeignKeyPartialSupportIndexRequired, error.RelationalIndexNotReady => jsonErrorResponse(ctx, 409, "foreign-key support changed or is still building; refresh the schema and retry"),
        error.ForeignKeyTargetNotUnique, error.ForeignKeyTypeMismatch, error.ForeignKeyParentTableNotFound => jsonErrorResponse(ctx, 400, "foreign key requires an existing parent with a matching ordered unique key and compatible scalar column types"),
        error.TableGenerationChanged, error.SchemaVersionChanged, error.TableTransitionActive, error.ConstraintRetirementInProgress => jsonErrorResponse(ctx, 409, "parent schema changed or has active maintenance; refresh and retry"),
        error.MetadataUnavailable, error.NotLeader, error.ProposalDropped => jsonErrorResponse(ctx, 503, "foreign-key support metadata is unavailable; retry"),
        error.SettingAuthorityUnavailable => jsonErrorResponse(ctx, 503, "metadata setting authority is not configured; contact an operator before retrying foreign-key publication"),
        error.InvalidSchemaUpdateRequest, error.InvalidCreateTableRequest => jsonErrorResponse(ctx, 400, "invalid relational schema definition"),
        error.UnsupportedRestoreSource => jsonErrorResponse(ctx, 409, "online schema rewrite requires row-derived indexes and completed source maintenance; independently authored artifacts are unsupported"),
        error.UnknownSchemaVersion, error.RestoreStagingScopeChanged => jsonErrorResponse(ctx, 409, "schema rewrite source definitions are incomplete or changed; verify source schema history and refresh before retrying"),
        error.InvalidOnlineSourceCommand => jsonErrorResponse(ctx, 409, "schema rewrite source ownership authority is not ready for this deployment; no rewrite was admitted"),
        error.OnlineSourceScopeChanged => jsonErrorResponse(ctx, 409, "schema rewrite source ownership changed or uses a different authority mode; refresh before retrying"),
        error.StorageKernelOwnerUnavailable, error.RestoreValidationPending, error.GroupLeaderUnavailable, error.UnknownGroup => jsonErrorResponse(ctx, 503, "schema rewrite source owner is unavailable; retry after owner recovery"),
        error.RelationalRewriteTypeChange => jsonErrorResponse(ctx, 400, "schema rewrite cannot change a stored column's scalar type"),
        error.RelationalRewriteColumnDrop => jsonErrorResponse(ctx, 400, "schema rewrite cannot silently drop stored columns"),
        error.RelationalRewriteRequiresRelational => jsonErrorResponse(ctx, 400, "schema rewrite cannot change the table storage mode"),
        error.RelationalRewriteBudgetExceeded => jsonErrorResponse(ctx, 413, "schema rewrite program exceeds its bounded schema or expression limit"),
        error.AsyncRestoreUnavailable => jsonErrorResponse(ctx, 503, "durable schema rewrite service is unavailable"),
        error.TransactionTooLarge => jsonErrorResponse(ctx, 413, "schema rewrite dependency cohort exceeds the bounded transaction limit"),
        error.InvalidIdempotencyKey => jsonErrorResponse(ctx, 400, "invalid Idempotency-Key"),
        error.IdempotencyConflict => jsonErrorResponse(ctx, 409, "Idempotency-Key was already used for a different rewrite"),
        error.StoredDestinationAuthorizationRevoked => jsonErrorResponse(ctx, 403, "schema rewrite administrator authorization is no longer valid"),
        error.MetadataMutationOutcomeUnknown => AntflyApiHandler.metadataMutationOutcomeUnknownResponse(ctx),
        else => err,
    };
}

const fk_publication_upgrade_message = "coordinated foreign-key publication requires a metadata cluster upgrade; no schema change was admitted";

fn fkPublicationUpgradeRequired(err: anyerror) bool {
    // Only the exact all-member decoder rejection proves the DDL was not
    // proposed. Unknown metadata or transport outcomes must retain their
    // separate recovery path and must never be advertised as safe to replay.
    return err == error.TableTopologyProtocolUpgradeRequired;
}

test "FK publication upgrade response excludes unknown mutation outcomes" {
    try std.testing.expect(fkPublicationUpgradeRequired(error.TableTopologyProtocolUpgradeRequired));
    try std.testing.expect(!fkPublicationUpgradeRequired(error.MetadataMutationOutcomeUnknown));
    try std.testing.expect(!fkPublicationUpgradeRequired(error.NotLeader));
}

test "FK publication reports missing setting authority as service unavailable" {
    var request = try httpx.Request.init(std.testing.allocator, .POST, "/tables/docs/schema");
    defer request.deinit();
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);
    defer ctx.deinit();
    var response = try witnessDDLError(&ctx, error.SettingAuthorityUnavailable);
    defer response.deinit();
    try std.testing.expectEqual(@as(u16, 503), response.status.code);
    try std.testing.expect(std.mem.indexOf(u8, response.body.?, "setting authority") != null);
}

