    return http_server_mod.foreignKeyParentsAllowed(alloc, identity, schema_json);
}

test "relational foreign key DDL requires referenced parent admin for create replace and patch" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"storage_mode":"relational","default_type":"row","foreign_keys":[{"name":"parent","child_columns":["parent_id"],"parent_table":"parents","parent_columns":["id"]}],"document_schemas":{"row":{"schema":{"type":"object","properties":{"parent_id":{"type":"integer"}},"additionalProperties":false}}}}
    ;
    var permissions = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .table, "children", .admin),
        try usermgr.Permission.initOwned(alloc, .table, "parents", .read),
    };
    defer for (&permissions) |*permission| permission.deinit(alloc);
    const identity = AuthenticatedIdentity{ .username = @constCast("author"), .permissions = &permissions };
    try std.testing.expect(!(try foreignKeyParentsAllowed(alloc, identity, schema_json)));
    const replacement = try table_contract.parseSchemaUpdateRequest(alloc, schema_json);
    defer alloc.free(replacement);
    try std.testing.expect(!(try foreignKeyParentsAllowed(alloc, identity, replacement)));
    const patched = try table_contract.mergeSchemaPatchRequest(alloc, schema_json, "{}");
    defer alloc.free(patched);
    try std.testing.expect(!(try foreignKeyParentsAllowed(alloc, identity, patched)));
    permissions[1].deinit(alloc);
    permissions[1] = try usermgr.Permission.initOwned(alloc, .table, "parents", .admin);
    try std.testing.expect(try foreignKeyParentsAllowed(alloc, identity, schema_json));
    try std.testing.expect(try foreignKeyParentsAllowed(alloc, identity, replacement));
    try std.testing.expect(try foreignKeyParentsAllowed(alloc, identity, patched));
}

fn replicationDestinationsAllowed(
    alloc: std.mem.Allocator,
    identity: ?AuthenticatedIdentity,
    replication_sources_json: []const u8,
) !bool {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, replication_sources_json, .{});
    defer parsed.deinit();
    const sources = switch (parsed.value) {
        .array => |array| array.items,
        else => return error.InvalidCreateTableRequest,
    };
    for (sources) |source| {
        if (source != .object) return error.InvalidCreateTableRequest;
        const routes_value = source.object.get("routes") orelse continue;
        if (routes_value == .null) continue;
        const configured_routes = switch (routes_value) {
            .array => |array| array.items,
            else => return error.InvalidCreateTableRequest,
        };
        for (configured_routes) |configured_route| {
            if (configured_route != .object) return error.InvalidCreateTableRequest;
            const target_value = configured_route.object.get("target_table") orelse return error.InvalidCreateTableRequest;
            const target_table = switch (target_value) {
                .string => |value| value,
                else => return error.InvalidCreateTableRequest,
            };
            if (target_table.len == 0) return error.InvalidCreateTableRequest;
            if (!(try storedDestinationAllowed(identity, target_table))) return false;
        }
    }
    return true;
}

fn graphResolverDestinationsAllowedInConfig(
    identity: ?AuthenticatedIdentity,
    config: std.json.Value,
) !bool {
    switch (config) {
        .object => |object| {
            if (object.get("resolvers")) |resolvers_value| {
                if (resolvers_value != .array) return error.InvalidCreateTableRequest;
                for (resolvers_value.array.items) |resolver| {
                    // String resolver references do not declare a destination here.
                    if (resolver == .string) continue;
                    if (resolver != .object) return error.InvalidCreateTableRequest;
                    const table_value = resolver.object.get("table") orelse continue;
                    if (table_value != .string or table_value.string.len == 0) return error.InvalidCreateTableRequest;
                    if (!(try storedDestinationAllowed(identity, table_value.string))) return false;
                }
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                if (std.mem.eql(u8, entry.key_ptr.*, "resolvers") or index_metadata.isOpaqueEntry(entry.key_ptr.*)) continue;
                if (!(try graphResolverDestinationsAllowedInConfig(identity, entry.value_ptr.*))) return false;
            }
        },
        .array => |array| for (array.items) |item| {
            if (!(try graphResolverDestinationsAllowedInConfig(identity, item))) return false;
        },
        else => {},
    }
    return true;
}

fn graphResolverDestinationsAllowed(
    alloc: std.mem.Allocator,
    identity: ?AuthenticatedIdentity,
    indexes_json: []const u8,
    single_index: bool,
) !bool {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();
    if (single_index) return try graphResolverDestinationsAllowedInConfig(identity, parsed.value);
    if (parsed.value != .object) return error.InvalidCreateTableRequest;
    return try graphResolverDestinationsAllowedInConfig(identity, parsed.value);
}

pub const RequestAdmission = http_server_mod.RequestAdmission;
const default_query_body_admission_capacity: usize = 32;
const authenticated_identity_context_key = "antfly.authenticated-identity";

const CachedAuthenticatedIdentity = struct {
    alloc: std.mem.Allocator,
    identity: ?AuthenticatedIdentity,

    fn destroy(raw: *anyopaque) void {
        const self: *@This() = @ptrCast(@alignCast(raw));
        if (self.identity) |*identity| identity.deinit(self.alloc);
        self.alloc.destroy(self);
    }
};

/// Lazy commitment preserves HTTP validation/auth errors until the first
/// event. Synchronous writes provide bounded transport backpressure while
/// the handler retains its request, identity, and query-admission lifetimes.
const RetrievalSseSink = struct {
    context: *httpx.Context,
    writer: ?httpx.Context.StreamWriter = null,
    failed: bool = false,

    fn iface(self: *@This()) retrieval_agent.EventSink {
        return .{ .sse_only = true, .ptr = self, .emit_json_fn = emitJson };
    }

    fn emitJson(raw: *anyopaque, _: std.mem.Allocator, name: []const u8, json: []const u8) !void {
        const self: *@This() = @ptrCast(@alignCast(raw));
        errdefer self.failed = true;
        if (self.context.isCancellationRequested()) return error.Canceled;
        if (self.writer == null) self.writer = try self.context.streamResponse(200);
        try self.writer.?.writeEvent(name, json);
    }

    fn emitError(self: *@This()) !void {
        try emitJson(self, self.context.allocator, "error", "{\"error\":\"RetrievalFailed\"}");
    }

    fn close(self: *@This()) !void {
        if (self.writer) |*writer| try writer.close();
    }
};

test "httpx retrieval SSE writes before generation and preserves terminal outcomes" {
    const State = struct {
        bytes: std.ArrayListUnmanaged(u8) = .empty,
        started: bool = false,
        closed: bool = false,
        generated: bool = false,
        fail_generation: bool = false,
        fail_query: bool = false,
        fail_write: bool = false,
        json_request: bool = false,
        forbidden: bool = false,
        cancelled: bool = false,

        fn authorize(raw: *anyopaque, _: []const u8, _: bool) !void {
            const self: *@This() = @ptrCast(@alignCast(raw));
            if (self.forbidden) return error.Forbidden;
        }
        fn isCancelled(raw: ?*const anyopaque) bool {
            const self: *const @This() = @ptrCast(@alignCast(raw.?));
            return self.cancelled;
        }

        fn start(raw: ?*anyopaque, status: u16, content_type: []const u8, _: *const httpx.Headers) !void {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            try std.testing.expectEqual(@as(u16, 200), status);
            try std.testing.expectEqualStrings("text/event-stream; charset=utf-8", content_type);
            try std.testing.expect(!self.started);
            self.started = true;
        }
        fn write(raw: ?*anyopaque, bytes: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            if (self.fail_write) return error.ConnectionResetByPeer;
            try std.testing.expect(std.unicode.utf8ValidateSlice(bytes));
            try self.bytes.appendSlice(std.testing.allocator, bytes);
        }
        fn close(raw: ?*anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(raw.?));
            try std.testing.expect(!self.closed);
            self.closed = true;
        }
        fn query(raw: *anyopaque, alloc: std.mem.Allocator, _: []const u8, _: []const u8) !query_api.QueryResponse {
            const self: *@This() = @ptrCast(@alignCast(raw));
            if (self.fail_query) return error.TableNotFound;
            return .{ .json = try alloc.dupe(u8,
                \\{"responses":[{"status":200,"took":1,"hits":{"hits":[{"_id":"doc:a","_score":1.0,"_source":{"content":"alpha"}}]}}]}
            ) };
        }
        fn generate(raw: *anyopaque, alloc: std.mem.Allocator, chain: []const generating_runtime.ChainLink, _: []const generating_runtime.ChatMessage) !generating_runtime.GenerateResult {
            const self: *@This() = @ptrCast(@alignCast(raw));
            self.generated = true;
            // No sleeps/timing races: the generation callback cannot begin
            // until the earlier hit has actually reached the transport.
            try std.testing.expectEqual(!self.json_request, self.started);
            if (!self.json_request) try std.testing.expect(std.mem.indexOf(u8, self.bytes.items, "event: hit\n") != null);
            try std.testing.expectEqual(@as(i64, 128), chain[0].generator.max_tokens);
            if (self.fail_generation) return error.TestGenerationFailure;
            return .{ .allocator = alloc, .content = try alloc.dupe(u8, (z17RepeatString("x", 79)) ++ "한국어 answer") };
        }
    };
    const alloc = std.testing.allocator;
    for (0..8) |case| {
        var state = State{ .fail_generation = case == 1, .fail_write = case == 2, .json_request = case == 3 or case == 7, .forbidden = case == 4, .cancelled = case == 5, .fail_query = case >= 6 };
        defer state.bytes.deinit(alloc);
        var request = try httpx.Request.init(alloc, .POST, "http://localhost/db/v1/agents/retrieval");
        defer request.deinit();
        var ctx = httpx.Context.init(alloc, std.testing.io, &request);
        defer ctx.deinit();
        ctx.stream_delegate = .{ .ptr = &state, .start = State.start, .write = State.write, .close = State.close };
        ctx.cancellation_probe = .{ .ptr = &state, .is_cancelled = State.isCancelled };
        var sink = RetrievalSseSink{ .context = &ctx };
        const body = try std.fmt.allocPrint(alloc,
            \\{{"query":"alpha","stream":{s},"generator":{{"provider":"antfly","model":"local","max_tokens":128}},"steps":{{"generation":{{"enabled":true}}}},"queries":[{{"table":"docs","full_text_search":{{"query":"body:alpha"}}}}]}}
        , .{if (state.json_request) "false" else "true"});
        defer alloc.free(body);
        const result = retrieval_agent.executeWithEventSink(alloc, .{ .ptr = &state, .vtable = &.{ .authorize_query = State.authorize, .run_query = State.query } }, .{ .ptr = &state, .vtable = &.{ .execute_chain = State.generate } }, body, sink.iface());
        if (state.fail_query and state.json_request) {
            try std.testing.expectError(error.TableNotFound, result);
            try std.testing.expect(!state.started);
            continue;
        }
        if (state.forbidden or state.cancelled) {
            try std.testing.expectError(if (state.forbidden) error.Forbidden else error.Canceled, result);
            try std.testing.expect(!state.started);
            try std.testing.expect(!state.generated);
            continue;
        }
        if (state.fail_write) {
            try std.testing.expectError(error.ConnectionResetByPeer, result);
            try std.testing.expect(sink.failed);
            try std.testing.expect(!state.generated);
            continue;
        }
        const encoded = try result;
        defer alloc.free(encoded.body);
        try sink.close();
        if (state.fail_query) {
            try std.testing.expect(!state.generated);
            try std.testing.expect(state.closed);
            try std.testing.expectEqual(@as(usize, 0), encoded.body.len);
            try std.testing.expectEqual(@as(usize, 1), std.mem.count(u8, state.bytes.items, "event: error\n"));
            try std.testing.expect(std.mem.indexOf(u8, state.bytes.items, "TableNotFound") != null);
            try std.testing.expect(std.mem.indexOf(u8, state.bytes.items, "event: done\n") == null);
            continue;
        }
        try std.testing.expect(state.generated);
        if (state.json_request) {
            try std.testing.expect(!state.started);
            try std.testing.expectEqualStrings("application/json", encoded.content_type);
            continue;
        }
        try std.testing.expect(state.closed);
        try std.testing.expectEqual(@as(usize, 0), encoded.body.len);
        try std.testing.expectEqual(!state.fail_generation, std.mem.indexOf(u8, state.bytes.items, "event: done\n") != null);
        try std.testing.expectEqual(state.fail_generation, std.mem.indexOf(u8, state.bytes.items, "GenerationFailed") != null);
        if (!state.fail_generation) try std.testing.expect(std.mem.indexOf(u8, state.bytes.items, "한국어") != null);
    }
}

/// Request-scoped database, web and fetch capabilities for native agents.
/// Shared by the retrieval and research handlers so both run under the same
/// authorization, deadline and cancellation.
const AgentQueryRunner = struct {
    server: *ApiHttpServer,
    source: table_reads.TableReadSource,
    query_embedding_security_scope: ApiHttpServer.QueryEmbeddingSecurityScope,
    authenticated_identity: ?AuthenticatedIdentity,
    request_context: managed_embedder.RequestContext,

    fn iface(runner: *@This()) retrieval_agent.QueryRunner {
        return .{
            .ptr = runner,
            .vtable = &.{
                .build_query = buildQuery,
                .authorize_query = authorizeQuery,
                .run_query = runQuery,
                .prepare_web_search = prepareWebSearch,
                .web_search = searchWeb,
                .fetch_url = fetchUrl,
                .scan_key_page = runScanKeyPage,
                .probe_incoming_edges = probeIncomingEdges,
            },
            .io = runner.server.agentConcurrencyIo(),
        };
    }

    fn fetchUrl(ptr: *anyopaque, arena: std.mem.Allocator, config: web_fetch.Config, url: []const u8) !web_fetch.Download {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        try runner.request_context.check();
        return fetchAgentUrl(arena, runner.request_context, config, url);
    }

    fn prepareWebSearch(ptr: *anyopaque, arena: std.mem.Allocator, options: web_search.Options) !web_search.Config {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        return web_search.resolve(arena, runner.server.cfg.node_config, options);
    }

    fn searchWeb(ptr: *anyopaque, arena: std.mem.Allocator, config: web_search.Config, query: []const u8) ![]const metadata_openapi.QueryHit {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        try runner.request_context.check();
        var client = httpx.Client.initWithConfig(arena, runner.request_context.io, .{ .retry_policy = .{ .max_retries = 0 } });
        defer client.deinit();
        const cancellation = if (runner.request_context.cancellation) |token| httpx.CancellationToken.fromCallback(token.ptr, token.is_cancelled_fn) else null;
        return web_search.search(arena, &client, runner.server.cfg.secret_store, config, query, runner.request_context.deadline_ns orelse (platform_time.monotonicNs() +| config.timeout_ms * std.time.ns_per_ms), cancellation);
    }

    fn buildQuery(ptr: *anyopaque, a: std.mem.Allocator, request: metadata_openapi.QueryBuilderRequest, generator: query_builder_agent.GenerationRunner) !metadata_openapi.QueryBuilderResult {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        return runner.server.buildRetrievalQuery(a, request, runner.authenticated_identity, runner.request_context, generator);
    }

    fn authorizeQuery(
        ptr: *anyopaque,
        table_name: []const u8,
        discovers_tree_roots: bool,
    ) !void {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        const identity = runner.authenticated_identity orelse return;
        if (!http_server_mod.permissionsAllow(identity.permissions, .table, table_name, .read))
            return error.Forbidden;
        // Physical reverse-index probes do not carry row filters. Keep
        // explicit-key and query-seeded tree traversal available, but
        // fail closed for structural root discovery.
        if (discovers_tree_roots and http_server_mod.effectiveRowFilterJson(identity, table_name) != null)
            return error.Forbidden;
    }

    fn runQuery(
        ptr: *anyopaque,
        a: std.mem.Allocator,
        table_name: []const u8,
        query_json: []const u8,
    ) !query_api.QueryResponse {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        try runner.request_context.check();
        return runner.server.executeCatalogRetrievalQuery(a, .{
            .deadline_ns = runner.request_context.deadline_ns,
            .cancellation = runner.request_context.cancellation orelse .none,
        }, table_name, query_json, runner.authenticated_identity);
    }

    fn runScanKeyPage(
        ptr: *anyopaque,
        a: std.mem.Allocator,
        logical_name: []const u8,
        after_key: []const u8,
        limit: u32,
        filter_query_json: ?[]const u8,
        exclusion_query_json: ?[]const u8,
    ) !retrieval_agent.QueryRunner.KeyPage {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        try runner.request_context.check();
        var catalog_identity = try http_server_mod.cloneCatalogIdentity(runner.server.alloc, runner.authenticated_identity);
        defer if (catalog_identity) |*owned| owned.deinit(runner.server.alloc);
        const table_name = try runner.server.resolveCatalogNameAlloc(a, .{
            .deadline_ns = runner.request_context.deadline_ns,
            .cancellation = runner.request_context.cancellation orelse .none,
        }, logical_name, &catalog_identity);
        defer a.free(table_name);
        if (catalog_identity) |identity| {
            if (!http_server_mod.permissionsAllow(identity.permissions, .table, table_name, .read))
                return error.Forbidden;
        }
        return try runner.server.scanRetrievalKeyPage(
            a,
            runner.source,
            table_name,
            after_key,
            limit,
            filter_query_json,
            exclusion_query_json,
            catalog_identity,
        );
    }

    fn probeIncomingEdges(
        ptr: *anyopaque,
        a: std.mem.Allocator,
        logical_name: []const u8,
        index_name: []const u8,
        keys: []const []const u8,
    ) ![]bool {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        try runner.request_context.check();
        var catalog_identity = try http_server_mod.cloneCatalogIdentity(runner.server.alloc, runner.authenticated_identity);
        defer if (catalog_identity) |*owned| owned.deinit(runner.server.alloc);
        const table_name = try runner.server.resolveCatalogNameAlloc(a, .{
            .deadline_ns = runner.request_context.deadline_ns,
            .cancellation = runner.request_context.cancellation orelse .none,
        }, logical_name, &catalog_identity);
        defer a.free(table_name);
        if (catalog_identity) |identity| {
            if (!http_server_mod.permissionsAllow(identity.permissions, .table, table_name, .read))
                return error.Forbidden;
            if (http_server_mod.effectiveRowFilterJson(identity, table_name) != null)
                return error.Forbidden;
        }
        return try runner.server.probeRetrievalIncomingEdges(
            a,
            runner.source,
            table_name,
            index_name,
            keys,
        );
    }
};

/// Request-scoped generation for native agents. Every model round is a
/// cancellation and deadline boundary.
const AgentGenerationRunner = struct {
    chatgpt: ?*@import("antfly_local_sources").chatgpt_manager.Manager = null,
    personal_owner: ?[]const u8 = null,
    chatgpt_pin: ?@import("antfly_local_sources").chatgpt_manager.Pin = null,
    chatgpt_failure: generating_runtime.ChatGPTFailure = .{},
    antfly_provider: ?managed_embedder.AntflyProvider,
    secret_store: ?*common_secrets.FileStore,
    io: std.Io,
    request_context: managed_embedder.RequestContext,
    inference_api_key: ?[]const u8,

    fn iface(runner: *@This()) retrieval_agent.GenerationRunner {
        return .{
            .ptr = runner,
            .vtable = &.{ .execute_chain = executeChain },
        };
    }

    fn executeChain(
        ptr: *anyopaque,
        a: std.mem.Allocator,
        chain: []const generating_runtime.ChainLink,
        messages: []const generating_runtime.ChatMessage,
    ) !generating_runtime.GenerateResult {
        const runner: *@This() = @ptrCast(@alignCast(ptr));
        for (chain) |link| if (link.generator.provider == .chatgpt) {
            const manager = runner.chatgpt orelse return error.ChatGPTDisabled;
            const owner = runner.personal_owner orelse return error.ChatGPTInteractiveOnly;
            const id = link.generator.connection_id orelse return error.InvalidGeneratorConfig;
            if (runner.chatgpt_pin == null) runner.chatgpt_pin = try manager.pinWithContext(owner, id, runner.request_context);
            try runner.chatgpt_pin.?.check(id);
        };
        // Each model round is a cancellation and deadline boundary.
        try runner.request_context.check();
        var client = httpx.Client.initWithConfig(a, runner.io, .{ .keep_alive = false });
        defer client.deinit();
        return try generating_runtime.executeChainWithOptions(a, &client, chain, .{ .chatgpt = runner.chatgpt, .chatgpt_failure = &runner.chatgpt_failure, .chatgpt_pin = runner.chatgpt_pin, .personal_owner = runner.personal_owner, .antfly_provider = runner.antfly_provider, .secret_store = runner.secret_store, .inference_api_key = runner.inference_api_key, .request_context = runner.request_context }, messages);
    }
};

/// Agent fetch downloads use the shared remote-content controls with
/// private-address blocking always on. Admission (allowed hosts or earlier
/// search results) happened before this call; redirects are re-validated
/// per hop by the downloader.
fn fetchAgentUrl(arena: std.mem.Allocator, request_context: managed_embedder.RequestContext, config: web_fetch.Config, url: []const u8) !web_fetch.Download {
    const security = scraping.ContentSecurityConfig{
        .block_private_ips = true,
        .max_download_size_bytes = config.max_download_bytes,
        .download_timeout_seconds = @intCast(@max(1, config.timeout_ms / std.time.ms_per_s)),
    };
    const remaining_ms = (try request_context.remainingTimeoutMs()) orelse config.timeout_ms;
    const outcome = try scraping.downloadContentOutcomeAllocWithContext(arena, .{
        .io = request_context.io,
        .timeout_ms = @min(config.timeout_ms, remaining_ms),
        .cancellation = if (request_context.cancellation) |token| scraping.CancellationToken.fromCallback(token.ptr, token.is_cancelled_fn) else null,
    }, url, &security, null);
    return switch (outcome) {
        .ok => |downloaded| .{ .content_type = downloaded.content_type, .data = downloaded.data },
        .http_error => error.FetchHttpError,
    };
}

pub const AntflyApiHandler = struct {
    api_server: *ApiHttpServer,
    /// Separate phase admission for H2 query bodies. Slow uploads must not
    /// consume execution permits, but still need a global waiter bound.
    query_body_admission: RequestAdmission = RequestAdmission.init(default_query_body_admission_capacity),

    /// Cancellation observation is owned by httpx. Retain this lifecycle hook
    /// while direct and linked handler construction share one interface.
    pub fn initRuntime(_: *AntflyApiHandler, _: std.mem.Allocator) !void {}

    /// Register the complete generated public surface for one handler
    /// instance. Runtime roles call this common registrar instead of carrying
    /// their own duplicate route arrays or active-handler globals.
    pub fn registerRoutes(self: *AntflyApiHandler, server: *httpx.Server) !void {
        try self.installMiddleware(server);
        return self.registerRoutesWithOptions(server, true, true);
    }

    /// Standalone owns a stronger readiness contract than the shared API
    /// kernel (listener publication, maintenance admission, and initialized
    /// API state), so it supplies the two root probe handlers itself.
    pub fn registerRoutesWithoutProbes(self: *AntflyApiHandler, server: *httpx.Server) !void {
        try self.installMiddleware(server);
        return self.registerRoutesWithOptions(server, true, false);
    }

    /// Metadata owns a distinct administration surface and must not expose
    /// data-node protocol or internal-group routes on its admin listener.
    pub fn registerGeneratedRoutesWithProbes(self: *AntflyApiHandler, server: *httpx.Server) !void {
        try self.installMiddleware(server);
        try self.registerRoutesWithOptions(server, false, true);
        try self.registerRaftAdminRoutes(server);
    }

    fn installMiddleware(self: *AntflyApiHandler, server: *httpx.Server) !void {
        try server.use(httpx.Middleware.bind("antfly-request-stats", self, recordRequest));
        try server.use(httpx.Middleware.bind("antfly-internal-service-auth", self, enforceInternalServiceAuth));
        try server.use(httpx.Middleware.bind("antfly-auth-before-encoded-body", self, authorizeBeforeEncodedBody));
        try server.use(httpx.Middleware.bind("antfly-request-content-encoding", self, decodeRequestContent));
        try server.use(httpx.Middleware.bind("antfly-ha-mutation-policy", self, enforceHotStandbyMutationPolicy));
    }

    /// Authenticate and authorize compressed requests before spending CPU or
    /// expanded-body memory on them. The owned identity is handed to the route
    /// handler through request context so password/API-key work is not repeated.
    fn authorizeBeforeEncodedBody(self: *AntflyApiHandler, ctx: *httpx.Context, next: *httpx.Next) !httpx.Response {
        const raw_encoding = ctx.header("content-encoding") orelse return next.call(ctx);
        if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, raw_encoding, " \t"), "identity")) return next.call(ctx);
        if (self.encodedBodyAuthorizationIsDeferred(ctx)) return next.call(ctx);

        var identity: ?AuthenticatedIdentity = null;
        defer if (identity) |*authenticated| authenticated.deinit(self.api_server.alloc);
        if (try self.authorizeRequest(ctx, &identity)) |response| return response;
        const authenticated = identity orelse return next.call(ctx);

        const cached = try self.api_server.alloc.create(CachedAuthenticatedIdentity);
        cached.* = .{ .alloc = self.api_server.alloc, .identity = authenticated };
        identity = null;
        ctx.setData(authenticated_identity_context_key, cached, CachedAuthenticatedIdentity.destroy) catch |err| {
            CachedAuthenticatedIdentity.destroy(cached);
            return err;
        };
        return next.call(ctx);
    }

    fn encodedBodyAuthorizationIsDeferred(self: *const AntflyApiHandler, ctx: *const httpx.Context) bool {
        const path = ctx.request.uri.path;
        if (requiresInternalServicePrincipal(path)) return true;
        if (std.mem.eql(u8, path, routes.healthz) or
            std.mem.eql(u8, path, routes.readyz) or
            std.mem.eql(u8, path, routes.agent_card)) return true;
        const public_catalog = std.mem.eql(u8, path, routes.ai_catalog) and self.api_server.cfg.ard_public_catalog_enabled;
        const carries_authentication = ctx.header("authorization") != null or
            ctx.header(http_server_mod.trusted_principal_header) != null;
        return public_catalog and !carries_authentication;
    }

    fn recordRequest(self: *AntflyApiHandler, ctx: *httpx.Context, next: *httpx.Next) !httpx.Response {
        self.api_server.recordHandledRequest();
        try self.api_server.reachRequestLifecycle(.ingress, null);
        try establishExecutionDeadlines(ctx);
        const response = next.call(ctx) catch |err| try mapIngressError(ctx, err);
        try self.api_server.reachRequestLifecycle(.response_ready, null);
        return response;
    }

    fn decodeRequestContent(_: *AntflyApiHandler, ctx: *httpx.Context, next: *httpx.Next) !httpx.Response {
        const raw_encoding = ctx.header("content-encoding") orelse return next.call(ctx);
        const encoding = std.mem.trim(u8, raw_encoding, " \t");
        if (std.ascii.eqlIgnoreCase(encoding, "identity")) return next.call(ctx);
        if (!std.ascii.eqlIgnoreCase(encoding, "gzip") and !std.ascii.eqlIgnoreCase(encoding, "x-gzip")) {
            return textResponse(ctx, 415, "unsupported content encoding");
        }

        const encoded = (try ctx.body()) orelse return textResponse(ctx, 400, "invalid gzip request body");
        const expanded_limit = @min(ctx.max_request_body_size, http_server_mod.public_api_max_request_body_bytes);
        const decoded = gunzipRequestBodyAlloc(ctx, ctx.allocator, encoded, expanded_limit) catch |err| switch (err) {
            error.RequestBodyTooLarge => return textResponse(ctx, 413, "request body too large"),
            error.BodyCapacityExceeded => {
                try ctx.setHeader("Retry-After", "1");
                return textResponse(ctx, 503, "request body capacity exhausted");
            },
            else => return textResponse(ctx, 400, "invalid gzip request body"),
        };
        try ctx.request.replaceOwnedBodyAllocation(decoded.body, decoded.allocation);
        _ = ctx.request.headers.remove("content-encoding");
        return next.call(ctx);
    }

    /// Every ingress path applies the same policies. A public budget cannot
    /// suppress validation or extend an internal service's admission bound.
    fn establishExecutionDeadlines(ctx: *httpx.Context) !void {
        try establishPublicExecutionDeadline(ctx);
        establishInternalRoutedBatchDeadline(ctx);
        establishInternalTxnPreDecisionDeadline(ctx);
        establishInternalTxnStatusDeadline(ctx);
        establishInternalBackupDeadline(ctx);
        establishInternalOnlineMergeDeadline(ctx);
        establishCatalogRouteFenceDeadline(ctx);
    }

    fn establishPublicExecutionDeadline(ctx: *httpx.Context) !void {
        const limits = @import("antfly_public_limits").Execution;
        const raw = ctx.header(limits.timeout_header) orelse return;
        const milliseconds = limits.positive(raw, limits.max_timeout_ms) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        @import("../request_deadline.zig").tighten(ctx, milliseconds);
        try ctx.setHeader("X-Antfly-Execution-Limits", "1");
    }

    fn sqlExecutionLimits(ctx: *httpx.Context) !sql_runtime.Limits {
        const controls = @import("antfly_public_limits").Execution;
        var result: sql_runtime.Limits = .{};
        if (ctx.header(controls.scan_rows_header)) |raw| result.scan_rows = @min(result.scan_rows, try controls.positive(raw, std.math.maxInt(usize)));
        if (ctx.header(controls.memory_header)) |raw| result.retained_bytes = @min(result.retained_bytes, try controls.positive(raw, std.math.maxInt(usize)));
        if (ctx.header(controls.spill_header)) |raw| result.spill_bytes = @min(result.spill_bytes, try controls.positive(raw, std.math.maxInt(u64)));
        return result;
    }

    fn establishInternalRoutedBatchDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        const raw = ctx.header(internal_batch_forwarding.remaining_ms_header) orelse return;
        const budget_ms = std.fmt.parseUnsigned(u32, raw, 10) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        if (budget_ms == 0 or budget_ms > internal_batch_forwarding.max_remaining_ms) {
            ctx.application_deadline_invalid = true;
            return;
        }
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    fn establishCatalogRouteFenceDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        if (ctx.header(metadata_api.catalog_route_fence_header) == null) return;
        const budget_ms = if (ctx.header(metadata_api.catalog_route_deadline_ms_header)) |raw|
            @import("antfly_public_limits").Execution.positive(raw, metadata_api.catalog_route_max_deadline_ms) catch {
                ctx.application_deadline_invalid = true;
                return;
            }
        else
            metadata_api.catalog_route_default_deadline_ms;
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    fn establishInternalTxnPreDecisionDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        const path = ctx.request.uri.path;
        if (routes.matchGroupTxnBegin(path) == null and routes.matchGroupTxnPrepare(path) == null) return;
        const raw = ctx.header(distributed_txn_contract.pre_decision_remaining_ms_header) orelse return;
        const budget_ms = std.fmt.parseUnsigned(u32, raw, 10) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        if (budget_ms == 0 or budget_ms > distributed_txn_contract.max_pre_decision_server_budget_ms) {
            ctx.application_deadline_invalid = true;
            return;
        }
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    fn establishInternalTxnStatusDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        if (routes.matchGroupTxnStatus(ctx.request.uri.path) == null) return;
        const raw = ctx.header(distributed_txn_contract.status_remaining_ms_header) orelse return;
        const budget_ms = std.fmt.parseUnsigned(u32, raw, 10) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        if (budget_ms == 0 or budget_ms > distributed_txn_contract.max_status_server_budget_ms) {
            ctx.application_deadline_invalid = true;
            return;
        }
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    fn establishInternalOnlineMergeDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        const contract = @import("online_merge_io.zig").contract;
        const path = ctx.request.uri.path;
        if (!std.mem.startsWith(u8, path, routes.internal_groups_prefix) or
            !std.mem.endsWith(u8, path, routes.online_merge_io_suffix)) return;
        const raw = ctx.header(contract.remaining_ms_header) orelse return;
        const budget_ms = std.fmt.parseUnsigned(u32, raw, 10) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        if (budget_ms == 0 or budget_ms > contract.max_server_budget_ms) {
            ctx.application_deadline_invalid = true;
            return;
        }
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    fn establishInternalBackupDeadline(ctx: *httpx.Context) void {
        if (ctx.application_deadline_invalid) return;
        const path = ctx.request.uri.path;
        if (!std.mem.startsWith(u8, path, routes.internal_groups_prefix) or
            !std.mem.endsWith(u8, path, routes.backup_shard_suffix)) return;
        const raw = ctx.header(backups_api.backup_remaining_ms_header) orelse return;
        const budget_ms = std.fmt.parseUnsigned(u32, raw, 10) catch {
            ctx.application_deadline_invalid = true;
            return;
        };
        if (budget_ms == 0 or budget_ms > backups_api.max_backup_server_budget_ms) {
            ctx.application_deadline_invalid = true;
            return;
        }
        @import("../request_deadline.zig").tighten(ctx, budget_ms);
    }

    /// Continuous-HA mutation safety belongs to ingress policy, not to a
    /// compatibility dispatcher or individual business handlers. The
    /// classifier consumes canonical application paths, so generated
    /// `/db/v1` routes and root contextual routes share one inventory.
    fn enforceHotStandbyMutationPolicy(self: *AntflyApiHandler, ctx: *httpx.Context, next: *httpx.Next) !httpx.Response {
        if (try self.hotStandbyMutationRejection(ctx)) |response| return response;
        return next.call(ctx);
    }

    /// Raw data-node routes bypass public table planning and RBAC by design, so
    /// they share one non-optional service-identity boundary before dispatch.
    /// The HA namespace retains its independent replication credential.
    fn enforceInternalServiceAuth(self: *AntflyApiHandler, ctx: *httpx.Context, next: *httpx.Next) !httpx.Response {
        if (try self.internalServiceAuthRejection(ctx)) |response| return response;
        if (ctx.application_deadline_invalid)
            return textResponse(ctx, 400, "invalid transaction deadline");
        return next.call(ctx);
    }

    fn internalServiceAuthRejection(self: *AntflyApiHandler, ctx: *httpx.Context) !?httpx.Response {
        if (!requiresInternalServicePrincipal(ctx.request.uri.path)) return null;
        const secret = self.api_server.cfg.internal_service_secret orelse
            return @as(?httpx.Response, try jsonErrorResponse(ctx, 503, "internal service authentication is not configured"));
        if (secret.len == 0)
            return @as(?httpx.Response, try jsonErrorResponse(ctx, 503, "internal service authentication is not configured"));
        const token = ctx.header(internal_service_auth.header_name) orelse {
            if (self.api_server.cfg.internal_service_accept_legacy_unauthenticated) {
                // This compatibility path is opt-in, startup-validated, and
                // intended only for the first half of a two-phase rolling
                // upgrade. Mark accepted responses so operators can verify old
                // peer traffic has drained before enabling enforcement.
                try ctx.setHeader("X-Antfly-Internal-Auth", "legacy-migration");
                return null;
            }
            return @as(?httpx.Response, try unauthorizedResponse(ctx));
        };
        var identity = self.api_server.authenticateInternalServiceRequest(token) catch
            return @as(?httpx.Response, try unauthorizedResponse(ctx));
        defer identity.deinit(self.api_server.alloc);
        if (!identity.is_internal_service)
            return @as(?httpx.Response, try jsonErrorResponse(ctx, 403, "internal service credential required"));
        return null;
    }

    /// Dispatch one route through the application-owned ingress policy.
    ///
    /// Direct registrations install the same policy as `httpx` middleware.
    /// Independently code-generated runtimes cannot carry that middleware
    /// through the route-manifest ABI, so their dispatch export must enter here
    /// instead of invoking the manifest's raw route handler. Keeping the
    /// policy in the API kernel also prevents host runtimes from duplicating
    /// application configuration or error classification.
    pub fn dispatchLinkedRoute(self: *AntflyApiHandler, ctx: *httpx.Context, route_handler: httpx.Handler) !httpx.Response {
        self.api_server.recordHandledRequest();
        try self.api_server.reachRequestLifecycle(.ingress, null);
        try establishExecutionDeadlines(ctx);
        if (try self.hotStandbyMutationRejection(ctx)) |response| {
            try self.api_server.reachRequestLifecycle(.response_ready, null);
            return response;
        }
        if (try self.internalServiceAuthRejection(ctx)) |response| {
            try self.api_server.reachRequestLifecycle(.response_ready, null);
            return response;
        }
        if (ctx.application_deadline_invalid) {
            const response = try textResponse(ctx, 400, "invalid transaction deadline");
            try self.api_server.reachRequestLifecycle(.response_ready, null);
            return response;
        }
        const response = route_handler.invoke(ctx) catch |err| try mapIngressError(ctx, err);
        try self.api_server.reachRequestLifecycle(.response_ready, null);
        return response;
    }

    /// Applies the kernel-owned internal-service boundary to a host-registered
    /// route. Production metadata routes live outside the generated route
    /// manifest, so the opaque host bridge calls this before their handlers.
    /// `legacy_accepted` lets the host preserve the migration acknowledgement
    /// header on the eventual application response.
    pub fn authorizeHostInternalServiceRoute(
        self: *AntflyApiHandler,
        ctx: *httpx.Context,
        legacy_accepted: *bool,
    ) !?httpx.Response {
        self.api_server.recordHandledRequest();
        legacy_accepted.* = ctx.header(internal_service_auth.header_name) == null and
            self.api_server.cfg.internal_service_accept_legacy_unauthenticated and
            requiresInternalServicePrincipal(ctx.request.uri.path);
        return self.internalServiceAuthRejection(ctx);
    }

    fn hotStandbyMutationRejection(self: *AntflyApiHandler, ctx: *httpx.Context) !?httpx.Response {
        const policy = self.api_server.hotStandbyMutationPolicy();
        if (!policy.failover_safe_mutations_only) return null;
        const path = http_server_mod.stripApiPrefix(ctx.request.uri.path);
        const mutation = classifyHotStandbyMutation(ctx.request.method, path) orelse return null;
        // Backup and table restore are adapters over the same durable cohort
        // and staging authority; handlers reject uncertified historical cuts.
        if ((mutation.surface == .cluster_restore or mutation.surface == .restore_job or mutation.surface == .table_restore or mutation.surface == .backup) and
            self.api_server.hotStandbyCoordinatedRestoreAvailable()) return null;
        if (policy.catalog_create_enabled and policy.remote_apply_mutations_enabled and
            mutation.surface == .table_catalog and ctx.request.method == .POST)
            return null;
        if (mutation.disposition != .reject and
            (mutation.disposition != .remote_apply or policy.remote_apply_mutations_enabled))
        {
            return null;
        }

        _ = ctx.status(503);
        return try ctx.json(.{
            .@"error" = "mutation is not continuously replicated while HA is active",
            .code = "ha_mutation_not_replicated",
            .surface = mutation.surface.wireName(),
        });
    }

    fn classifyHotStandbyMutation(method: httpx.Method, path: []const u8) ?hot_standby_mutation_inventory.Classification {
        const inventory_method: http_common.Method = switch (method) {
            .GET, .HEAD, .OPTIONS => return null,
            .POST => .POST,
            .PUT => .PUT,
            .DELETE => .DELETE,
            // The inventory's deliberately small method type makes every new
            // mutation verb opt in. Do not let a future PATCH or custom route
            // bypass continuous-HA durability policy merely because the
            // application-method adapter has not learned that verb yet.
            else => return .{
                .surface = .unclassified_non_get,
                .disposition = .reject,
            },
        };
        return hot_standby_mutation_inventory.classify(inventory_method, path);
    }

    fn metadataNotLeaderResponse(ctx: *httpx.Context) !httpx.Response {
        _ = ctx.status(503);
        try ctx.setHeader("content-type", "application/json");
        try ctx.setHeader("Retry-After", "1");
        try ctx.setHeader(http_common.metadata_not_leader_header, http_common.metadata_not_leader_value);
        _ = ctx.response.body("{\"code\":\"metadata_leader_unavailable\",\"error\":\"metadata leader unavailable\",\"message\":\"metadata leader unavailable\",\"retryable\":true,\"retry_after_ms\":1000}");
        return ctx.response.build();
    }

    fn markMetadataMutationNotAdmitted(ctx: *httpx.Context) !void {
        // This is stronger than the metadata routing hint: callers may replay
        // a mutation only when the authority layer proved that no proposal was
        // admitted. Keep this marker off ambiguous and read-only failures.
        try ctx.setHeader(
            http_common.metadata_mutation_not_admitted_header,
            http_common.metadata_mutation_not_admitted_value,
        );
    }

    fn metadataMutationNotAdmittedResponse(ctx: *httpx.Context) !httpx.Response {
        try markMetadataMutationNotAdmitted(ctx);
        return metadataNotLeaderResponse(ctx);
    }

    fn metadataMutationNotAdmittedTextResponse(ctx: *httpx.Context, message: []const u8) !httpx.Response {
        try markMetadataMutationNotAdmitted(ctx);
        try ctx.setHeader("Retry-After", "1");
        _ = ctx.status(503);
        return ctx.text(message);
    }

    fn metadataMutationOutcomeUnknownResponse(ctx: *httpx.Context) !httpx.Response {
        try ctx.setHeader(
            metadata_http_routes.Routes.raft_mutation_outcome_header,
            metadata_http_routes.Routes.raft_mutation_outcome_unknown,
        );
        _ = ctx.status(409);
        return ctx.text("table mutation outcome is unknown; observe table state before retrying");
    }

    fn mapIngressError(ctx: *httpx.Context, err: anyerror) !httpx.Response {
        if (metadata_authority.isRetryableError(err)) return metadataNotLeaderResponse(ctx);
        return err;
    }

    fn registerRoutesWithOptions(
        self: *AntflyApiHandler,
        server: *httpx.Server,
        include_contextual: bool,
        include_probes: bool,
    ) !void {
        var prefixed = PrefixedServer("/db/v1", httpx.Server){ .inner = server };
        try self.registerRouteSets(&prefixed, server, include_contextual, include_probes);
    }

    /// One generated route manifest shared by native servers and the linked
    /// kernel registrar boundary. `public_server` already represents the
    /// `/db/v1` namespace; `root_server` owns root-level APIs such as auth.
    pub fn registerRouteSets(
        self: *AntflyApiHandler,
        public_server: anytype,
        root_server: anytype,
        include_contextual: bool,
        include_probes: bool,
    ) !void {
        try root_server.get("/ai/v1/models", httpx.Handler.bind(self, gatewayModels));
        try root_server.postResponseStreaming("/ai/v1/chat/completions", httpx.Handler.bind(self, gatewayChat));
        try root_server.postResponseStreaming("/ai/v1/embeddings", httpx.Handler.bind(self, gatewayEmbeddings));
        try root_server.postResponseStreaming("/ai/v1/decisions", httpx.Handler.bind(self, gatewayDecisions));
        try root_server.postResponseStreaming("/ai/v1/read", httpx.Handler.bind(self, gatewayRead));
        try root_server.postResponseStreaming("/ai/v1/extract", httpx.Handler.bind(self, gatewayExtract));
        try root_server.postResponseStreaming("/ai/v1/rewrite", httpx.Handler.bind(self, gatewayRewrite));
        try root_server.postResponseStreaming("/ai/v1/transcribe", httpx.Handler.bind(self, gatewayTranscribe));
        try root_server.postResponseStreaming("/ai/v1/synthesize", httpx.Handler.bind(self, gatewaySynthesize));
        try root_server.postResponseStreaming("/ai/v1/rerank", httpx.Handler.bind(self, gatewayRerank));
        try root_server.postResponseStreaming("/ai/v1/chunk", httpx.Handler.bind(self, gatewayChunk));
        try root_server.postResponseStreaming("/ml/v1/predict", httpx.Handler.bind(self, gatewayPredict));
        try root_server.postResponseStreaming("/ai/v1/dictate", httpx.Handler.bind(self, gatewayDictate));
        try root_server.postResponseStreaming("/ai/v1/embed", httpx.Handler.bind(self, gatewayEmbed));
        try root_server.postResponseStreaming("/ai/v1/generate", httpx.Handler.bind(self, gatewayGenerate));
        try root_server.postResponseStreaming("/ai/v1/generate/batch", httpx.Handler.bind(self, gatewayBatch));
        try root_server.get("/ml/v1/models", httpx.Handler.bind(self, gatewayModels));
        try root_server.get("/ml/v1/predictors", httpx.Handler.bind(self, gatewayModels));
        try root_server.postResponseStreaming("/ai/v1/transcription/sessions", httpx.Handler.bind(self, gatewaySessionCreate));
        try root_server.get("/ai/v1/transcription/sessions/:session_id", httpx.Handler.bind(self, gatewaySessionGet));
        try root_server.delete("/ai/v1/transcription/sessions/:session_id", httpx.Handler.bind(self, gatewaySessionDelete));
        try root_server.postResponseStreaming("/ai/v1/transcription/sessions/:session_id/audio", httpx.Handler.bind(self, gatewaySessionAudio));
        try root_server.get("/ai/v1/transcription/sessions/:session_id/events", httpx.Handler.bind(self, gatewaySessionEvents));
        try root_server.postStreamingRaw("/ai/v1/transcription/sessions/:session_id/stream", httpx.Handler.bind(self, gatewaySessionStream));

        const metadata_router = metadata_server_openapi.server.ServerRouter(AntflyApiHandler).init(self);
        try metadata_router.register(public_server);
        try public_server.get("/tables/:table_name/sources/managed", httpx.Handler.bind(self, managedSourceStatus));
        try public_server.post("/tables/:table_name/sources/managed", httpx.Handler.bind(self, configureManagedSources));
        try public_server.post("/tables/:table_name/lake/reconcile", httpx.Handler.bind(self, reconcileLakeSource));
        const usermgr_router = usermgr_server_openapi.server.ServerRouter(AntflyApiHandler).init(self);
        try usermgr_router.register(root_server);
        const memory_handler = httpx.Handler.bind(self, memoryRoute);
        try root_server.post("/memory/v1/spaces", memory_handler);
        inline for (.{ "/memory/v1/spaces/:memory_space", "/memory/v1/spaces/:memory_space/*" }) |path| {
            try root_server.get(path, memory_handler);
            try root_server.post(path, memory_handler);
            try root_server.put(path, memory_handler);
            try root_server.patch(path, memory_handler);
        }
        if (include_contextual) {
            try self.registerContextualRoutes(root_server, include_probes);
        } else if (include_probes) {
            try self.registerProbes(root_server);
        }
    }

    /// Hand-written protocol, operational, administrative, and internal
    /// routes share this registrar in every runtime role. The generated data
    /// API remains available only below `/db/v1`; historical root aliases are
    /// intentionally not registered.
    fn registerContextualRoutes(self: *AntflyApiHandler, server: anytype, include_probes: bool) !void {
        if (include_probes) {
            try self.registerProbes(server);
        }

        const mcp_paths = [_][]const u8{ routes.mcp_v1, routes.mcp_v1_prefix ++ "*", routes.memory_mcp_v1 };
        const mcp_handler = httpx.Handler.bind(self, mcpRoute);
        inline for (mcp_paths) |path| {
            try server.get(path, mcp_handler);
            try server.post(path, mcp_handler);
            try server.delete(path, mcp_handler);
        }
        if (self.api_server.cfg.experimental) {
            try server.post(routes.a2a, httpx.Handler.bind(self, a2aRoute));
            const a2a_card_handler = httpx.Handler.bind(self, a2aCardRoute);
            try server.get(routes.agent_card, a2a_card_handler);
        }

        const ard_handler = httpx.Handler.bind(self, ardRoute);
        try server.get(routes.ai_catalog, ard_handler);
        try server.get(routes.ard_v1, ard_handler);
        try server.get(routes.ard_v1 ++ "/*", ard_handler);
        try server.post(routes.ard_v1_search, ard_handler);
        try server.post(routes.ard_v1_explore, ard_handler);

        const extension_paths = [_][]const u8{
            routes.extensions_v1,
            routes.extensions_v1_packages,
            routes.extensions_v1_packages_prefix ++ "*",
            routes.extensions_v1_installed,
            routes.extensions_v1_installed_prefix ++ "*",
        };
        const extension_handler = httpx.Handler.bind(self, extensionRoute);
        inline for (extension_paths) |path| {
            try server.get(path, extension_handler);
            try server.post(path, extension_handler);
            try server.put(path, extension_handler);
        }
        const extension_agent_handler = httpx.Handler.bind(self, extensionAgentRoute);
        try server.get(routes.agents_v1_extensions_prefix ++ "*", extension_agent_handler);
        try server.post(routes.agents_v1_extensions_prefix ++ "*", extension_agent_handler);
        try server.put(routes.agents_v1_extensions_prefix ++ "*", extension_agent_handler);

        // Canonical `/admin/v1/standby` and the pre-0.3 `/admin/v1/ha` alias;
        // the hot-standby handler normalises the path before dispatch.
        const hot_standby_admin_paths = [_][]const u8{
            admin_routes.standby,
            admin_routes.standby ++ "/*",
            admin_routes.legacy_standby_prefix,
            admin_routes.legacy_standby_prefix ++ "/*",
        };
        const hot_standby_handler = httpx.Handler.bind(self, hotStandbyRoute);
        inline for (hot_standby_admin_paths) |path| {
            try server.get(path, hot_standby_handler);
            try server.post(path, hot_standby_handler);
            try server.put(path, hot_standby_handler);
            try server.delete(path, hot_standby_handler);
        }
        try server.post(admin_routes.maintenance_check, httpx.Handler.bind(self, checkStorage));
        try server.post(admin_routes.maintenance_compact, httpx.Handler.bind(self, compactStorage));
        try server.post(admin_routes.maintenance_vacuum, httpx.Handler.bind(self, vacuumStorage));
