    fn internalGroupBackupShard(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse
            return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse
            return textResponse(ctx, 400, "invalid backup shard request");
        if (ctx.header(@import("antfly_local_sources").api_backup_contract.backup_pin_control_header)) |version| {
            if (!std.mem.eql(u8, version, "v1") or body.len > 4096) return textResponse(ctx, 400, "invalid backup pin control");
            var parsed = std.json.parseFromSlice(@import("antfly_local_sources").storage_db_native_backup_seal.Request, ctx.allocator, body, .{}) catch
                return textResponse(ctx, 400, "invalid backup pin control");
            defer parsed.deinit();
            const source = self.api_server.table_writes orelse return textResponse(ctx, 503, "backup owner unavailable");
            const request = self.api_server.boundedBackupRequest(operationContext(ctx, null));
            const response = source.backupPinControl(ctx.allocator, params.table_name, params.group_id, parsed.value, .{ .deadline_ns = request.deadline_ns.?, .cancellation = request.cancellation, .owner_local_only = true }) catch |err| {
                if (backup_pin_diagnostic_gate.admit(platform_time.monotonicNs()))
                    std.log.warn("backup pin failed phase=owner_dispatch action={s} group_id={d} class={s}", .{ @tagName(parsed.value), params.group_id, @errorName(err) });
                return switch (err) {
                    error.InvalidBackupFence => textResponse(ctx, 400, "invalid backup pin owner"),
                    error.IntegrityTopologyChanged, error.IntegrityTopologyMissing, error.IntegrityCatalogChanged, error.CatalogChanged => textResponse(ctx, 409, "backup pin authority changed"),
                    else => textResponse(ctx, 503, "backup pin operation must be retried"),
                };
            };
            defer if (response) |value| ctx.allocator.free(value);
            return if (response) |value| jsonResponse(ctx, 200, value) else textResponse(ctx, 404, "backup owner not found");
        }
        const expected_fence = backups_api.parseTableBackupFenceHeaderValuesWithDeadline(
            ctx.header(backups_api.backup_fence_metadata_group_id_header),
            ctx.header(backups_api.backup_fence_metadata_incarnation_header),
            ctx.header(backups_api.backup_fence_table_id_header),
            ctx.header(backups_api.backup_fence_definition_header),
            ctx.header(backups_api.backup_fence_topology_count_header),
            ctx.header(backups_api.backup_fence_topology_header),
            ctx.header(backups_api.backup_writer_not_after_header),
        ) catch return textResponse(ctx, 400, "invalid backup fence");
        const fence = expected_fence orelse return textResponse(ctx, 400, "backup fence required");
        var parsed = backups_api.parseBackupRequest(ctx.allocator, body) catch
            return textResponse(ctx, 400, "invalid backup shard request");
        defer parsed.deinit();
        backups_api.validateBackupId(parsed.value.backup_id) catch
            return textResponse(ctx, 400, "invalid backup id");
        const format = backups_api.parseBackupFormat(parsed.value.format) catch
            return textResponse(ctx, 400, "unsupported backup format");
        var location = backups_api.openBackupLocationWithOptions(ctx.allocator, parsed.value.location, .{
            .secret_store = self.api_server.cfg.secret_store,
            .node_config = self.api_server.cfg.node_config,
            .connection = parsed.value.connection,
            .required_capability = "backup.write",
            .network_io = self.api_server.sharedApiNetworkIo(),
            .filesystem_io = self.api_server.sharedApiFilesystemIo(),
        }) catch return textResponse(ctx, 400, "invalid backup location");
        defer location.deinit(ctx.allocator);

        const cohort = @import("antfly_local_sources").api_backup_contract.parseBackupCohortFenceHeader(ctx.header(@import("antfly_local_sources").api_backup_contract.backup_cohort_fence_header)) catch
            return textResponse(ctx, 400, "invalid backup cohort fence");
        const sealed_raw = ctx.header(@import("antfly_local_sources").api_backup_contract.backup_sealed_handle_header);
        if (sealed_raw != null and (cohort != null or sealed_raw.?.len > 4096)) return textResponse(ctx, 400, "invalid sealed backup authority");
        var sealed: ?std.json.Parsed(@import("antfly_local_sources").api_backup_contract.SealedHandle) = if (sealed_raw) |value|
            std.json.parseFromSlice(@import("antfly_local_sources").api_backup_contract.SealedHandle, ctx.allocator, value, .{}) catch return textResponse(ctx, 400, "invalid sealed backup authority")
        else
            null;
        defer if (sealed) |*value| value.deinit();
        const shards = self.api_server.executeInternalTableBackupShardCohort(
            params.group_id,
            params.table_name,
            parsed.value.backup_id,
            format,
            fence,
            &location,
            operationContext(ctx, null),
            cohort,
            if (sealed) |value| &.{value.value} else &.{},
        ) catch |err| return switch (err) {
            error.TableNotFound, error.NotFound => textResponse(ctx, 404, "not found"),
            error.CatalogChanged => textResponse(ctx, 409, "table catalog changed"),
            error.IntegrityTopologyChanged, error.IntegrityTopologyFenceMissing, error.IntegrityCatalogChanged => textResponse(ctx, 409, "backup cohort changed"),
            error.TransactionTopologyBusy => textResponse(ctx, 503, "backup cohort is draining"),
            error.BackupAttemptLeaseLost, error.InvalidBackupFence => textResponse(ctx, 409, "backup writer lease lost"),
            error.UnsupportedBackupFormat => textResponse(ctx, 400, "unsupported backup format"),
            error.BackupOutcomeAmbiguous => textResponse(ctx, 500, "backup outcome ambiguous"),
            error.Canceled, error.Cancelled => blk: {
                try ctx.setHeader(backups_api.backup_outcome_header, backups_api.backup_outcome_stopped_v1);
                break :blk textResponse(ctx, 408, "backup canceled");
            },
            error.Timeout, error.DeadlineExceeded => blk: {
                try ctx.setHeader(backups_api.backup_outcome_header, backups_api.backup_outcome_stopped_v1);
                break :blk textResponse(ctx, 504, "backup deadline exceeded");
            },
            else => textResponse(ctx, 500, "internal server error"),
        };
        defer {
            for (shards) |shard| shard.deinit(self.api_server.alloc);
            self.api_server.alloc.free(shards);
        }
        return ctx.json(.{ .shards = shards });
    }

    fn internalGroupLookup(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const encoded_key = ctx.param("key") orelse return textResponse(ctx, 400, "invalid path parameter");
        const key = (try decodePathParamOrBadRequest(ctx, encoded_key)) orelse
            return textResponse(ctx, 400, "invalid path parameter");
        defer ctx.allocator.free(key);
        var lookup_options = http_route_helpers.parseInternalLookupOptions(
            ctx.allocator,
            ctx.request.uri.query orelse "",
        ) catch return textResponse(ctx, 400, "invalid lookup options");
        defer lookup_options.deinit(ctx.allocator);
        if (ctx.request.method == .POST) {
            const token = ctx.header(internal_service_auth.header_name) orelse return unauthorizedResponse(ctx);
            var identity = self.api_server.authenticateInternalServiceRequest(token) catch return unauthorizedResponse(ctx);
            defer identity.deinit(self.api_server.alloc);
            if (!identity.is_internal_service) return textResponse(ctx, 403, "internal service credential required");
            // Two spellings must not disagree about which control is routed.
            if (lookup_options.opts.relational_integrity_jobs_json.len != 0 or lookup_options.opts.relational_integrity_catalog or lookup_options.opts.relational_integrity_action or
                lookup_options.opts.relational_activation_json.len != 0 or lookup_options.opts.relational_topology_json.len != 0 or
                lookup_options.opts.relational_index_status_json.len != 0 or lookup_options.opts.group_source_query_json.len != 0)
                return textResponse(ctx, 400, "ambiguous lookup controls");
            const body = (try ctx.body()) orelse return textResponse(ctx, 400, "lookup control body required");
            if (body.len == 0 or body.len > @import("antfly_local_sources").storage_db_relational_integrity_contract.max_preparation_bytes)
                return textResponse(ctx, 413, "lookup control body too large");
            // Context owns these bytes through dispatch; OwnedLookupOptions
            // only frees query buffers that it allocated itself.
            lookup_options.opts.relational_integrity_jobs_json = body;
        }
        const policy_authority = @import("../usermgr/mod.zig").row_policy_authority;
        const policy_token = ctx.header(policy_authority.principal_header);
        const policy_database = ctx.header(policy_authority.database_header);
        var decoded_policy_database: ?[]u8 = null;
        defer if (decoded_policy_database) |value| ctx.allocator.free(value);
        if (policy_token != null or policy_database != null) {
            // A legacy unauthenticated internal route must not turn a user
            // capability into an unfiltered integrity observation.
            const service_token = ctx.header(internal_service_auth.header_name) orelse return unauthorizedResponse(ctx);
            var service_identity = self.api_server.authenticateInternalServiceRequest(service_token) catch return unauthorizedResponse(ctx);
            defer service_identity.deinit(self.api_server.alloc);
            if (!service_identity.is_internal_service) return textResponse(ctx, 403, "internal service credential required");
            const token = policy_token orelse return textResponse(ctx, 400, "missing policy principal");
            const database = policy_database orelse return textResponse(ctx, 400, "missing policy database");
            if (token.len == 0 or token.len > policy_authority.maximum_token_bytes or database.len == 0 or database.len > 3 * policy_authority.maximum_name_bytes or !lookup_options.opts.include_primary_digest)
                return textResponse(ctx, 400, "invalid policy observation authority");
            decoded_policy_database = (try decodePathParamOrBadRequest(ctx, database)) orelse return textResponse(ctx, 400, "invalid policy database");
            if (decoded_policy_database.?.len == 0 or decoded_policy_database.?.len > policy_authority.maximum_name_bytes)
                return textResponse(ctx, 400, "invalid policy database");
            lookup_options.opts.row_policy_principal_proof = token;
            lookup_options.opts.row_policy_database = decoded_policy_database.?;
        }
        if (std.mem.eql(u8, lookup_options.opts.relational_topology_json, "{\"mode\":\"generation_handoff_install\"}") or
            std.mem.eql(u8, lookup_options.opts.relational_topology_json, "{\"mode\":\"generation_handoff_identity\"}"))
        {
            // A legacy unauthenticated internal peer must never gain the
            // hidden, unfenced receipt capability merely by setting a query
            // parameter. Public route middleware is not sufficient here.
            const token = ctx.header(internal_service_auth.header_name) orelse return unauthorizedResponse(ctx);
            var identity = self.api_server.authenticateInternalServiceRequest(token) catch return unauthorizedResponse(ctx);
            defer identity.deinit(self.api_server.alloc);
            if (!identity.is_internal_service) return textResponse(ctx, 403, "internal service credential required");
        }
        const control_lookup = lookup_options.opts.group_source_query_json.len != 0 or lookup_options.opts.relational_integrity_catalog or lookup_options.opts.relational_integrity_jobs_json.len != 0 or lookup_options.opts.relational_index_status_json.len != 0 or lookup_options.opts.relational_activation_json.len != 0 or lookup_options.opts.relational_topology_json.len != 0;
        const logical_key = if (control_lookup and std.mem.eql(u8, key, "\x00relational_control")) "" else key;
        const consistency = http_server_mod.parseLookupReadConsistency(ctx.request.uri.query orelse "") catch
            return textResponse(ctx, 400, "invalid read consistency");
        var result = self.internalGroupOperations().lookup(
            ctx.allocator,
            operationContext(ctx, null),
            .{
                .group_id = params.group_id,
                .table_name = params.table_name,
                .key = logical_key,
                .options = lookup_options.opts,
                .consistency = consistency,
            },
        ) catch |err| return internalLookupErrorResponse(ctx, err);
        defer result.deinit(ctx.allocator);
        var version_buf: [20]u8 = undefined;
        const version = try std.fmt.bufPrint(&version_buf, "{d}", .{result.version});
        try ctx.setHeader("X-Antfly-Version", version);
        if (result.expected_content_digest) |digest| {
            const hex = std.fmt.bytesToHex(digest, .lower);
            try ctx.setHeader("X-Antfly-Primary-Digest", &hex);
        }
        return ownedJsonResponse(ctx, 200, &result.json, ctx.allocator);
    }

    fn internalJoinJobState(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        const body = (try ctx.body()) orelse return textResponse(ctx, 400, "invalid join job state request");
        var input = std.json.parseFromSlice(
            @import("distributed_join.zig").EncodedJoinJobStateRequest,
            ctx.allocator,
            body,
            .{ .ignore_unknown_fields = true },
        ) catch return textResponse(ctx, 400, "invalid join job state request");
        defer input.deinit();
        var result = (internal_join_operations.Operations{ .job_store = &self.api_server.join_job_store }).jobState(
            ctx.allocator,
            operationContext(ctx, null),
            input.value.job_id,
        ) catch |err| return switch (err) {
            error.NotFound => textResponse(ctx, 404, "not found"),
            error.Canceled => textResponse(ctx, 408, "request canceled"),
            error.DeadlineExceeded => textResponse(ctx, 504, "request deadline exceeded"),
            else => textResponse(ctx, 500, "internal server error"),
        };
        defer result.deinit();
        return ctx.json(result.parsed.value);
    }

