    fn internalQueryContext(self: *AntflyApiHandler, ctx: *httpx.Context) internal_query_operations.Context {
        var result = self.api_server.internalQueryContext();
        if (result.query_planning) |*planning| {
            planning.query_cancellation = operationContext(ctx, null).cancellation;
        }
        return result;
    }

    fn internalQueryPlanningErrorResponse(ctx: *httpx.Context, err: anyerror) !httpx.Response {
        if (err == error.InvalidQueryRequest or err == error.UnsupportedQueryRequest)
            return textResponse(ctx, 400, @errorName(err));
        const normalized = internal_query_operations.normalizeQueryEmbeddingOperationalError(err) orelse return err;
        return switch (normalized) {
            error.QueryEmbeddingInputTooLarge => textResponse(ctx, 413, "query embedding input too large"),
            error.QueryEmbeddingOverloaded => textResponse(ctx, 429, "query embedding overloaded"),
            error.EmbedRateLimited => textResponse(ctx, 429, "query embedding rate limited"),
            error.EmbedTransientFailure => textResponse(ctx, 503, "query embedding temporarily unavailable"),
            error.EmbedUpstreamFailure => textResponse(ctx, 502, "query embedding provider failed"),
            error.Timeout => textResponse(ctx, 504, "query embedding timed out"),
            else => unreachable,
        };
    }

    fn routeInternalQuery(
        query_context: internal_query_operations.Context,
        ctx: *httpx.Context,
        table_name: []const u8,
        request: *db_mod.types.SearchRequest,
    ) !?httpx.Response {
        const prepared = @import("prepared_query_routing.zig");
        const applied = prepared.apply(ctx.allocator, table_name, ctx.header(prepared.header_name), ctx.header(metadata_api.catalog_route_fence_header), request) catch |err| return try textResponse(ctx, 400, @errorName(err));
        if (applied) return null;
        query_context.routeQuery(table_name, request) catch |err| {
            const response = switch (err) {
                error.TableNotFound => try textResponse(ctx, 404, @errorName(err)),
                error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => try textResponse(ctx, 500, "invalid table metadata"),
                else => return err,
            };
            return @as(?httpx.Response, response);
        };
        return null;
    }

    fn internalQueryResponse(ctx: *httpx.Context, result: *query_api.QueryResponse) !httpx.Response {
        try @import("query_response_validation.zig").validate(ctx.allocator, result.json);
        if (result.identity_read_generation) |generation| {
            var buf: [32]u8 = undefined;
            const value = try std.fmt.bufPrint(&buf, "{d}", .{generation});
            try ctx.setHeader(query_api.QueryResponse.identity_read_generation_header, value);
        }
        return ownedJsonResponse(ctx, 200, &result.json, ctx.allocator);
    }

    fn internalGroupQuery(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse "";
        const query_context = self.internalQueryContext(ctx);
        var query_request = query_context.planQuery(ctx.allocator, params.table_name, body) catch |err|
            return internalQueryPlanningErrorResponse(ctx, err);
        defer query_request.deinit(ctx.allocator);
        query_request.req.cancellation = operationContext(ctx, null).cancellation;
        if (try routeInternalQuery(query_context, ctx, params.table_name, &query_request.req)) |response| return response;
        var result = self.internalGroupOperations().query(
            ctx.allocator,
            operationContext(ctx, null),
            params.group_id,
            params.table_name,
            query_request.req,
        ) catch |err| return if (err == error.InvalidArgument)
            textResponse(ctx, 400, @errorName(err))
        else
            internalGroupErrorResponse(ctx, err);
        defer result.deinit(ctx.allocator);
        return internalQueryResponse(ctx, &result);
    }

    const InternalQueryPreflightWire = struct {
        query_request: std.json.Value,
        max_work: u32 = 0,
    };

    fn parseInternalQueryPreflight(
        alloc: std.mem.Allocator,
        body: []const u8,
    ) !struct { query_request_body: []u8, max_work: u32 } {
        var parsed = std.json.parseFromSlice(InternalQueryPreflightWire, alloc, body, .{ .allocate = .alloc_always }) catch {
            return .{
                .query_request_body = try alloc.dupe(u8, body),
                .max_work = 0,
            };
        };
        defer parsed.deinit();
        return .{
            .query_request_body = try std.json.Stringify.valueAlloc(alloc, parsed.value.query_request, .{}),
            .max_work = parsed.value.max_work,
        };
    }

    fn internalGroupQueryPreflight(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse "";
        const preflight = try parseInternalQueryPreflight(ctx.allocator, body);
        defer ctx.allocator.free(preflight.query_request_body);
        const query_context = self.internalQueryContext(ctx);
        var query_request = query_context.planQuery(ctx.allocator, params.table_name, preflight.query_request_body) catch |err|
            return internalQueryPlanningErrorResponse(ctx, err);
        defer query_request.deinit(ctx.allocator);
        query_request.req.cancellation = operationContext(ctx, null).cancellation;
        if (try routeInternalQuery(query_context, ctx, params.table_name, &query_request.req)) |response| return response;
        var summary = self.internalGroupOperations().queryPreflight(
            ctx.allocator,
            operationContext(ctx, null),
            params.group_id,
            params.table_name,
            query_request.req,
            preflight.max_work,
        ) catch |err| return if (err == error.InvalidArgument)
            textResponse(ctx, 400, @errorName(err))
        else
            internalGroupErrorResponse(ctx, err);
        defer summary.deinit(ctx.allocator);
        return ctx.json(summary);
    }

    fn internalGroupVectorWorker(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse "";
        var envelope = query_contract.parseAlgebraicVectorWorkerRequestEnvelopeAlloc(ctx.allocator, body) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return textResponse(ctx, 400, "invalid vector worker request"),
        };
        defer envelope.deinit(ctx.allocator);
        var query_request = query_contract.searchRequestFromVectorWorkerEnvelope(&envelope);
        defer if (query_request.primary_text_index_name) |index_name| ctx.allocator.free(index_name);
        query_request.cancellation = operationContext(ctx, null).cancellation;
        const query_context = self.internalQueryContext(ctx);
        if (try routeInternalQuery(query_context, ctx, params.table_name, &query_request)) |response| return response;
        var result = self.internalGroupOperations().query(
            ctx.allocator,
            operationContext(ctx, null),
            params.group_id,
            params.table_name,
            query_request,
        ) catch |err| return if (err == error.InvalidArgument)
            textResponse(ctx, 400, @errorName(err))
        else
            internalGroupErrorResponse(ctx, err);
        defer result.deinit(ctx.allocator);
        return internalQueryResponse(ctx, &result);
    }

    fn internalRetainedRead(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        const rpc = @import("retained_read_rpc.zig");
        // Unlike legacy stateless internal reads, retained handles NEVER accept
        // unsigned migration traffic. Bind each operation to the authenticated
        // service credential, not a principal supplied by the request body.
        const credential = ctx.header(internal_service_auth.header_name) orelse return unauthorizedResponse(ctx);
        var identity = self.api_server.authenticateInternalServiceRequest(credential) catch return unauthorizedResponse(ctx);
        defer identity.deinit(self.api_server.alloc);
        if (!identity.is_internal_service) return textResponse(ctx, 403, "internal service credential required");
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse return textResponse(ctx, 400, "missing retained read request");
        if (body.len > rpc.max_request_bytes) return textResponse(ctx, 413, "retained read request too large");
        var request_budget: SQLMemoryBudget = .{ .backing = ctx.allocator, .limit = 16 << 20 };
        var parsed = std.json.parseFromSlice(rpc.Request, request_budget.allocator(), body, .{ .parse_numbers = false }) catch return textResponse(ctx, 400, "invalid retained read request");
        defer parsed.deinit();
        const request = operationContext(ctx, null);
        try request.ensureActive();
        var source = self.api_server.table_reads orelse return textResponse(ctx, 503, "retained read source unavailable");
        source.bindCatalogRouteFenceJson(ctx.allocator, request.catalog_route_fence_json, params.group_id, request.deadline_ns, request.cancellation) catch return textResponse(ctx, 400, "invalid catalog route fence");
        const route = source.route_fence orelse return textResponse(ctx, 400, "catalog route fence required");
        var principal: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(identity.credential_principal, &principal, .{});
        const runtime = self.api_server.retainedReadRuntime() catch return textResponse(ctx, 503, "retained read owner unavailable");
        const encoded = rpc.executeWithCodec(ctx.allocator, .{ .registry = &runtime.registry, .source = source }, .{
            .principal = principal,
            .authorization_revision = 1,
            .table_id = route.table_id,
            .group_id = route.route.group_id,
            .topology_revision = route.topology_epoch,
            .schema_version = parsed.value.schema_version,
        }, params.table_name, parsed.value, @import("retained_read_page.zig").formatForAccept(ctx.header("accept") orelse "")) catch |err| {
            if (parsed.value.operation == .normalize)
                return textResponse(ctx, rpc.normalizationFailureHttpStatus(err), @errorName(err));
            return textResponse(ctx, switch (err) {
                error.InvalidRetainedReadLease, error.InvalidRetainedReadToken, error.InvalidRetainedReadQuery, error.InvalidRetainedReadPageLimit => 400,
                error.RetainedReadAdmissionExceeded, error.RetainedReadBusy => 429,
                error.RetainedReadNotFound, error.RetainedReadExpired, error.RetainedReadScopeChanged, error.RetainedReadSequenceMismatch, error.SqlRangeTrackingRequired => 409,
                else => 503,
            }, @errorName(err));
        };
        defer ctx.allocator.free(encoded);
        try ctx.setHeader("content-type", if (std.mem.startsWith(u8, encoded, @import("retained_read_page.zig").compact_magic)) @import("retained_read_page.zig").compact_media_type else if (std.mem.startsWith(u8, encoded, @import("retained_read_page.zig").magic)) @import("retained_read_page.zig").media_type else "application/json");
        return ctx.response.body(try ctx.allocator.dupe(u8, encoded)).build();
    }

    fn internalGroupScan(self: *AntflyApiHandler, ctx: *httpx.Context) !httpx.Response {
        var params = (try internalGroupTableParams(ctx)) orelse return textResponse(ctx, 400, "invalid path parameter");
        defer params.deinit(ctx.allocator);
        const body = (try ctx.body()) orelse "";
        var input = http_route_helpers.parseInternalScanKeysRequest(ctx.allocator, body) catch |err| return switch (err) {
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => textResponse(ctx, 400, "invalid scan request"),
            else => err,
        };
        defer input.deinit(ctx.allocator);
        const request = operationContext(ctx, null);
        input.opts.execution_deadline_ns = request.deadline_ns;
        if (request.cancellation.ptr != null and request.cancellation.is_cancelled_fn != null)
            input.opts.cancellation = request.cancellation;
        const HttpScanSink = struct {
            ctx: *httpx.Context,
            writer: ?httpx.Context.StreamWriter = null,

            fn sink(state: *@This()) table_reads.ScanStreamSink {
                return .{ .context = state, .start_fn = start, .write_fn = write };
            }

            fn start(raw: ?*anyopaque) !void {
                const state: *@This() = @ptrCast(@alignCast(raw orelse return error.InvalidArgument));
                if (state.writer == null)
                    state.writer = try state.ctx.streamResponseWithContentType(200, "application/x-ndjson");
            }

            fn write(raw: ?*anyopaque, bytes: []const u8) !void {
                const state: *@This() = @ptrCast(@alignCast(raw orelse return error.InvalidArgument));
                if (state.writer == null) try start(state);
                try state.writer.?.write(bytes);
            }
        };
        var stream = HttpScanSink{ .ctx = ctx };
        const found = self.internalGroupOperations().scanStream(
            ctx.allocator,
            request,
            params.group_id,
            params.table_name,
            input.from,
            input.to,
            input.opts,
            stream.sink(),
        ) catch |err| {
            if (stream.writer != null) return err;
            return internalGroupErrorResponse(ctx, err);
        };
        if (!found) return internalGroupErrorResponse(ctx, error.NotFound);
        try stream.writer.?.close();
        return ctx.response.build();
    }

