    // ---------------------------------------------------------------
    // Authentication helper
    // ---------------------------------------------------------------

    fn authenticate(self: *AntflyApiHandler, ctx: *httpx.Context) !?AuthenticatedIdentity {
        if (!self.api_server.cfg.auth_enabled and self.api_server.cfg.trusted_principal_secret == null and
            ctx.header(http_server_mod.trusted_principal_header) == null) return null;
        return self.api_server.authenticateRequest(.{
            .authorization = ctx.header("authorization"),
            .trusted_principal = ctx.header(http_server_mod.trusted_principal_header),
        }) catch |err| switch (err) {
            error.Unauthorized, error.InvalidPassword, error.UserNotFound, error.ApiKeyInvalid, error.ApiKeyNotFound, error.ApiKeyExpired => {
                return null;
            },
            else => return err,
        };
    }

    fn requireAuth(self: *AntflyApiHandler, ctx: *httpx.Context) !?AuthenticatedIdentity {
        if (!self.api_server.cfg.auth_enabled and self.api_server.cfg.trusted_principal_secret == null and
            ctx.header(http_server_mod.trusted_principal_header) == null) return null;
        const identity = (try self.authenticate(ctx)) orelse {
            return error.Unauthorized;
        };
        return identity;
    }

    fn requestMethod(ctx: *httpx.Context) ?http_server_mod.AuthorizationMethod {
        return switch (ctx.request.method) {
            .GET => .GET,
            .HEAD => .HEAD,
            .POST => .POST,
            .PUT => .PUT,
            .PATCH => .PATCH,
            .DELETE => .DELETE,
            else => null,
        };
    }

    fn ownedJsonResponse(ctx: *httpx.Context, status: u16, body: *[]u8, owner: std.mem.Allocator) !httpx.Response {
        _ = ctx.status(status);
        try ctx.setHeader("content-type", "application/json");
        _ = ctx.response.bodyOwned(owner, body.*);
        body.* = &.{};
        return ctx.response.build();
    }

    fn jsonResponse(ctx: *httpx.Context, status: u16, body: []const u8) !httpx.Response {
        _ = ctx.status(status);
        try ctx.setHeader("content-type", "application/json");
        _ = ctx.response.body(body);
        return ctx.response.build();
    }

    fn jsonErrorResponse(ctx: *httpx.Context, status: u16, message: []const u8) !httpx.Response {
        _ = ctx.status(status);
        return ctx.json(.{ .@"error" = message });
    }

    fn textResponse(ctx: *httpx.Context, status: u16, body: []const u8) !httpx.Response {
        _ = ctx.status(status);
        try ctx.setHeader("content-type", "text/plain");
        _ = ctx.response.body(body);
        return ctx.response.build();
    }

    const CommittedMutationOutcome = enum { visibility_pending, superseded, repair_required, repair_unavailable };

    fn committedMutationOutcomeResponse(ctx: *httpx.Context, outcome: CommittedMutationOutcome) !httpx.Response {
        const header_value = switch (outcome) {
            .visibility_pending => metadata_http_routes.Routes.raft_mutation_outcome_committed_visibility_pending,
            .superseded => metadata_http_routes.Routes.raft_mutation_outcome_committed_superseded,
            .repair_required, .repair_unavailable => metadata_http_routes.Routes.raft_mutation_outcome_committed_repair_required,
        };
        try ctx.setHeader(metadata_http_routes.Routes.raft_mutation_outcome_header, header_value);
        if (outcome == .visibility_pending) try ctx.setHeader("Retry-After", "1");
        _ = ctx.status(202);
        return ctx.json(.{ .status = switch (outcome) {
            .visibility_pending => "committed_visibility_pending",
            .superseded => "committed_superseded",
            .repair_required => "committed_repair_required",
            .repair_unavailable => "committed_repair_unavailable",
        } });
    }

    fn queryOverloadedResponse(ctx: *httpx.Context) !httpx.Response {
        try ctx.setHeader("Retry-After", "1");
        // HTTP/2 has stream-local overload and forbids connection-specific
        // headers. HTTP/1 must close rejected keep-alive sockets promptly so
        // they do not retain connection-admission permits.
        if (ctx.h1_sock != null) try ctx.setHeader("Connection", "close");
        return textResponse(ctx, 429, "query capacity exhausted");
    }

    fn writeOverloadedResponse(ctx: *httpx.Context) !httpx.Response {
        try ctx.setHeader("Retry-After", "1");
        if (ctx.h1_sock != null) try ctx.setHeader("Connection", "close");
        return textResponse(ctx, 429, "write capacity exhausted");
    }

