};

test "system catalog SQL setting publication requires cluster admin and forwards only an admitted grant" {
    const alloc = std.testing.allocator;
    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();
    var admin_permission = try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin);
    defer admin_permission.deinit(alloc);
    var admin = try auth.manager.createUser("settings_admin", "secret", &.{admin_permission});
    defer admin.deinit(alloc);
    var reader_permission = try usermgr.Permission.initOwned(alloc, .table, "*", .read);
    defer reader_permission.deinit(alloc);
    var reader = try auth.manager.createUser("settings_reader", "secret", &.{reader_permission});
    defer reader.deinit(alloc);
    const Source = struct {
        calls: usize = 0,
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{}, .projected_stores = 1 };
        }
        fn catalog(ptr: *anyopaque, a: std.mem.Allocator, context: operation_contract.RequestContext, call: @import("../system_catalog/server_call.zig").Call) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (!context.setting_admin or call != .setting_mutate or call.setting_mutate != .put) return error.TestUnexpectedResult;
            self.calls += 1;
            return a.dupe(u8, "{\"revision\":1}");
        }
        fn iface(self: *@This()) http_server_mod.StatusSource {
            return .{ .ptr = self, .vtable = &.{ .status = status, .system_catalog = catalog } };
        }
    };
    var source = Source{};
    var api_server = ApiHttpServer.init(alloc, .{ .auth_enabled = true, .user_manager = &auth.manager }, source.iface(), null, null);
    defer api_server.deinit();
    var e2e: HttpxE2eServer = undefined;
    try e2e.init(alloc, &api_server);
    defer e2e.deinit();
    var io = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io.deinit();
    var client = httpx.Client.initWithConfig(alloc, io.io(), .{ .keep_alive = false });
    defer client.deinit();
    const base = try e2e.baseUrl(alloc);
    defer alloc.free(base);
    const url = try std.fmt.allocPrint(alloc, "{s}/db/v1/settings", .{base});
    defer alloc.free(url);
    const body = "{\"put\":{\"name\":\"app.tenant\",\"kind\":\"string\",\"policy_sensitive\":true,\"default\":{\"string\":\"none\"},\"role_defaults\":[{\"principal\":\"settings_reader\",\"database\":\"main\",\"value\":{\"string\":\"alpha\"}}]}}";
    const reader_auth = try encodeBasicAuthorization(alloc, "settings_reader", "secret");
    defer alloc.free(reader_auth);
    const admin_auth = try encodeBasicAuthorization(alloc, "settings_admin", "secret");
    defer alloc.free(admin_auth);
    const reader_headers = [_][2][]const u8{ .{ "authorization", reader_auth }, .{ "content-type", "application/json" } };
    var denied = try requestWithRetry(&client, io.io(), .POST, url, body, &reader_headers, 20);
    defer denied.deinit();
    try std.testing.expectEqual(@as(u16, 403), denied.status.code);
    try std.testing.expectEqual(@as(usize, 0), source.calls);
    const admin_headers = [_][2][]const u8{ .{ "authorization", admin_auth }, .{ "content-type", "application/json" } };
    var allowed = try requestWithRetry(&client, io.io(), .POST, url, body, &admin_headers, 20);
    defer allowed.deinit();
    try std.testing.expectEqual(@as(u16, 200), allowed.status.code);
    try std.testing.expectEqual(@as(usize, 1), source.calls);
}

test "public index publication recovery requires table admin and preserves exact logical scope" {
    const alloc = std.testing.allocator;
    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();
    var permission = try usermgr.Permission.initOwned(alloc, .table, "*", .admin);
    defer permission.deinit(alloc);
    var admin = try auth.manager.createUser("index_admin", "secret", &.{permission});
    defer admin.deinit(alloc);
    var read_permission = try usermgr.Permission.initOwned(alloc, .table, "*", .read);
    defer read_permission.deinit(alloc);
    var reader = try auth.manager.createUser("index_reader", "secret", &.{read_permission});
    defer reader.deinit(alloc);
    const Source = struct {
        calls: usize = 0,
        database: []const u8 = "default",
        namespace: []const u8 = "public",
        replaced: bool = false,
        wrong_incarnation: bool = false,
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{}, .projected_stores = 1 };
        }
        fn catalog(ptr: *anyopaque, a: std.mem.Allocator, context: operation_contract.RequestContext, call: @import("../system_catalog/server_call.zig").Call) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expect(context.setting_admin and context.index_publication_authority);
            try std.testing.expect(!call.isMutation());
            self.calls += 1;
            switch (call) {
                .resolve_many => |request| {
                    try std.testing.expectEqual(@as(usize, 1), request.relations.len);
                    try std.testing.expectEqualStrings(self.database, request.relations[0].database);
                    try std.testing.expectEqualStrings(self.namespace, request.relations[0].namespace);
                    try std.testing.expectEqualStrings("items/a", request.relations[0].name);
                    const domain = @import("antfly_local_sources").system_catalog_domain;
                    const id: u64 = if (self.replaced) 102 else 101;
                    return std.json.Stringify.valueAlloc(a, domain.ResolvedMany{
                        .revision = 9,
                        .tables = &.{},
                        .relation_epoch = .{ .incarnation = @splat(0x11), .revision = 9 },
                        .relations = &.{.{ .table = .{ .table_id = id, .name = "physical:101" }, .logical_table = "items/a", .owner = .{ .kind = .table, .table_id = id, .schema_version = 3, .schema_digest = @splat(4) } }},
                    }, .{});
                },
                .relational_index_status => |request| {
                    if (self.wrong_incarnation) return error.MetadataIncarnationMismatch;
                    try std.testing.expectEqualStrings("by/email", request.index_name);
                    try std.testing.expectEqualStrings("items/a", request.guard.logical_table);
                    return std.json.Stringify.valueAlloc(a, @import("../metadata/relational_index_publication.zig").AdmissionStatus{ .metadata_incarnation = @splat('1') }, .{});
                },
                else => return error.TestUnexpectedResult,
            }
        }
        fn iface(self: *@This()) http_server_mod.StatusSource {
            return .{ .ptr = self, .vtable = &.{ .status = status, .system_catalog = catalog } };
        }
    };
    var source: Source = .{};
    var api_server = ApiHttpServer.init(alloc, .{ .auth_enabled = true, .user_manager = &auth.manager }, source.iface(), null, null);
    defer api_server.deinit();
    var e2e: HttpxE2eServer = undefined;
    try e2e.init(alloc, &api_server);
    defer e2e.deinit();
    var threaded = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer threaded.deinit();
    var client = httpx.Client.initWithConfig(alloc, threaded.io(), .{ .keep_alive = false });
    defer client.deinit();
    const base = try e2e.baseUrl(alloc);
    defer alloc.free(base);
    const url = try std.fmt.allocPrint(alloc, "{s}/db/v1/tables/items%2Fa/indexes/by%2Femail/publication", .{base});
    defer alloc.free(url);
    const token = try @import("index_publication_recovery.zig").Token.encode(.{ .metadata_incarnation = @splat('1'), .table_id = 101, .id = @splat(2), .plan_digest = @splat(3) });
    const reader_auth = try encodeBasicAuthorization(alloc, "index_reader", "secret");
    defer alloc.free(reader_auth);
    const admin_auth = try encodeBasicAuthorization(alloc, "index_admin", "secret");
    defer alloc.free(admin_auth);
    const reader_headers = [_][2][]const u8{ .{ "authorization", reader_auth }, .{ "X-Antfly-Index-Publication-Token", &token } };
    var denied = try getWithRetry(&client, threaded.io(), url, &reader_headers, 20);
    defer denied.deinit();
    try std.testing.expectEqual(@as(u16, 403), denied.status.code);
    try std.testing.expectEqual(@as(usize, 0), source.calls);
    const missing_headers = [_][2][]const u8{.{ "authorization", admin_auth }};
    var missing = try getWithRetry(&client, threaded.io(), url, &missing_headers, 20);
    defer missing.deinit();
    try std.testing.expectEqual(@as(u16, 400), missing.status.code);
    try std.testing.expectEqual(@as(usize, 0), source.calls);
    const admin_headers = [_][2][]const u8{ .{ "authorization", admin_auth }, .{ "X-Antfly-Index-Publication-Token", &token } };
    var allowed = try getWithRetry(&client, threaded.io(), url, &admin_headers, 20);
    defer allowed.deinit();
    try std.testing.expectEqual(@as(u16, 200), allowed.status.code);
    var result = try std.json.parseFromSlice(@import("antfly_indexes_openapi").types.IndexPublicationStatus, alloc, allowed.body.?, .{});
    defer result.deinit();
    try std.testing.expectEqualStrings(&token, result.value.publication_token);
    try std.testing.expectEqual(@import("antfly_indexes_openapi").types.IndexPublicationState.admission_unknown, result.value.state);
    try std.testing.expectEqual(@as(usize, 2), source.calls);
    source.database = "warehouse";
    source.namespace = "sales";
    const scoped_url = try std.fmt.allocPrint(alloc, "{s}/db/v1/databases/warehouse/namespaces/sales/tables/items%2Fa/indexes/by%2Femail/publication", .{base});
    defer alloc.free(scoped_url);
    var scoped = try getWithRetry(&client, threaded.io(), scoped_url, &admin_headers, 20);
    defer scoped.deinit();
    try std.testing.expectEqual(@as(u16, 200), scoped.status.code);
    try std.testing.expectEqual(@as(usize, 4), source.calls);
    source.replaced = true;
    var replaced = try getWithRetry(&client, threaded.io(), scoped_url, &admin_headers, 20);
    defer replaced.deinit();
    try std.testing.expectEqual(@as(u16, 409), replaced.status.code);
    try std.testing.expectEqual(@as(usize, 5), source.calls);
    source.replaced = false;
    source.wrong_incarnation = true;
    var foreign = try getWithRetry(&client, threaded.io(), scoped_url, &admin_headers, 20);
    defer foreign.deinit();
    try std.testing.expectEqual(@as(u16, 409), foreign.status.code);
    try std.testing.expectEqual(@as(usize, 7), source.calls);
}

test "store-root enrollment requires cluster admin and forwards only valid possession proof" {
    const alloc = std.testing.allocator;
    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();
    var admin_permission = try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin);
    defer admin_permission.deinit(alloc);
    var admin = try auth.manager.createUser("root_admin", "secret", &.{admin_permission});
    defer admin.deinit(alloc);
    var reader_permission = try usermgr.Permission.initOwned(alloc, .table, "*", .read);
    defer reader_permission.deinit(alloc);
    var reader = try auth.manager.createUser("root_reader", "secret", &.{reader_permission});
    defer reader.deinit(alloc);
    const Source = struct {
        calls: usize = 0,
        status_reads: usize = 0,
        mismatch_enroll: bool = false,
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{}, .projected_stores = 1 };
        }
        fn catalog(ptr: *anyopaque, a: std.mem.Allocator, context: operation_contract.RequestContext, call: @import("../system_catalog/server_call.zig").Call) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (!context.setting_admin) return error.TestUnexpectedResult;
            switch (call) {
                .store_root_enroll => |request| {
                    try request.validate();
                    self.calls += 1;
                    var result = request.identity;
                    if (self.mismatch_enroll) result.root_incarnation += 1;
                    return std.json.Stringify.valueAlloc(a, result, .{});
                },
                .store_root_enrollment_status => |requested| {
                    try requested.validate();
                    self.status_reads += 1;
                    return std.json.Stringify.valueAlloc(a, requested, .{});
                },
                else => return error.TestUnexpectedResult,
            }
        }
        fn iface(self: *@This()) http_server_mod.StatusSource {
            return .{ .ptr = self, .vtable = &.{ .status = status, .system_catalog = catalog } };
        }
    };
    var source = Source{};
    var api_server = ApiHttpServer.init(alloc, .{ .auth_enabled = true, .user_manager = &auth.manager }, source.iface(), null, null);
    defer api_server.deinit();
    var e2e: HttpxE2eServer = undefined;
    try e2e.init(alloc, &api_server);
    defer e2e.deinit();
    var io = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io.deinit();
    var client = httpx.Client.initWithConfig(alloc, io.io(), .{ .keep_alive = false });
    defer client.deinit();
    const base = try e2e.baseUrl(alloc);
    defer alloc.free(base);
    const url = try std.fmt.allocPrint(alloc, "{s}/db/v1/store-roots/enroll", .{base});
    defer alloc.free(url);
    const seed: [32]u8 = @splat(7);
    const pair = try std.crypto.sign.Ed25519.KeyPair.generateDeterministic(seed);
    const proof = try @import("../metadata/store_root_enrollment.zig").Request.sign(.{
        .metadata_incarnation = "0123456789abcdef0123456789abcdef".*,
        .node_id = 3,
        .store_id = 5,
        .root_incarnation = 7,
        .public_key = pair.public_key.toBytes(),
    }, seed);
    const body = try @import("store_root_enrollment_http.zig").encodeAlloc(alloc, proof);
    defer alloc.free(body);
    const reader_auth = try encodeBasicAuthorization(alloc, "root_reader", "secret");
    defer alloc.free(reader_auth);
    const admin_auth = try encodeBasicAuthorization(alloc, "root_admin", "secret");
    defer alloc.free(admin_auth);
    const reader_headers = [_][2][]const u8{ .{ "authorization", reader_auth }, .{ "content-type", "application/json" } };
    var denied = try requestWithRetry(&client, io.io(), .POST, url, body, &reader_headers, 20);
    defer denied.deinit();
    try std.testing.expectEqual(@as(u16, 403), denied.status.code);
    try std.testing.expectEqual(@as(usize, 0), source.calls);
    const admin_headers = [_][2][]const u8{ .{ "authorization", admin_auth }, .{ "content-type", "application/json" } };
    var invalid = try requestWithRetry(&client, io.io(), .POST, url, "{}", &admin_headers, 20);
    defer invalid.deinit();
    try std.testing.expectEqual(@as(u16, 400), invalid.status.code);
    var allowed = try requestWithRetry(&client, io.io(), .POST, url, body, &admin_headers, 20);
    defer allowed.deinit();
    try std.testing.expectEqual(@as(u16, 200), allowed.status.code);
    try std.testing.expect(std.mem.indexOf(u8, allowed.body orelse "", "\"root_incarnation\":\"7\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, allowed.body orelse "", "\"public_key\":\"") != null);
    try std.testing.expectEqual(@as(usize, 1), source.calls);
    source.mismatch_enroll = true;
    var mismatched = try requestWithRetry(&client, io.io(), .POST, url, body, &admin_headers, 20);
    defer mismatched.deinit();
    try std.testing.expectEqual(@as(u16, 503), mismatched.status.code);
    try std.testing.expectEqual(@as(usize, 2), source.calls);
    source.mismatch_enroll = false;
    const status_url = try std.fmt.allocPrint(alloc, "{s}/db/v1/store-roots/enrollment-status", .{base});
    defer alloc.free(status_url);
    const status_body = try @import("store_root_enrollment_http.zig").encodeIdentityAlloc(alloc, proof.identity);
    defer alloc.free(status_body);
    var denied_status = try requestWithRetry(&client, io.io(), .POST, status_url, status_body, &reader_headers, 20);
    defer denied_status.deinit();
    try std.testing.expectEqual(@as(u16, 403), denied_status.status.code);
    try std.testing.expectEqual(@as(usize, 0), source.status_reads);
    var allowed_status = try requestWithRetry(&client, io.io(), .POST, status_url, status_body, &admin_headers, 20);
    defer allowed_status.deinit();
    try std.testing.expectEqual(@as(u16, 200), allowed_status.status.code);
    try std.testing.expect(std.mem.indexOf(u8, allowed_status.body orelse "", "\"root_incarnation\":\"7\"") != null);
    try std.testing.expectEqual(@as(usize, 1), source.status_reads);
    try std.testing.expectEqual(@as(usize, 2), source.calls);
}

test "compressed requests authenticate before decompression and reuse the identity" {
    if (comptime builtin.os.tag == .windows or builtin.os.tag == .freestanding) return;

    const alloc = std.testing.allocator;
    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var table_read = try usermgr.Permission.initOwned(alloc, .table, "*", .read);
    defer table_read.deinit(alloc);
    var reader = try auth.manager.createUser("reader", "reader", &.{table_read});
    defer reader.deinit(alloc);
    const authorization = try encodeBasicAuthorization(alloc, "reader", "reader");
    defer alloc.free(authorization);

    var source = AuthStatusSource{};
    var api_server = ApiHttpServer.init(alloc, .{
        .auth_enabled = true,
        .user_manager = &auth.manager,
    }, source.iface(), null, null);
    defer api_server.deinit();
    var e2e_server: HttpxE2eServer = undefined;
    try e2e_server.init(alloc, &api_server);
    defer e2e_server.deinit();

    var client_io = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer client_io.deinit();
    var client = httpx.Client.initWithConfig(alloc, client_io.io(), .{ .keep_alive = false });
    defer client.deinit();
    const base_url = try e2e_server.baseUrl(alloc);
    defer alloc.free(base_url);
    const url = try std.fmt.allocPrint(alloc, "{s}/db/v1/query", .{base_url});
    defer alloc.free(url);

    const anonymous_headers = [_][2][]const u8{
        .{ "content-type", "application/json" },
        .{ "content-encoding", "gzip" },
    };
    var anonymous = try requestWithRetry(&client, client_io.io(), .POST, url, "not gzip", &anonymous_headers, 20);
    defer anonymous.deinit();
    try std.testing.expectEqual(@as(u16, 401), anonymous.status.code);

    const authenticated_headers = [_][2][]const u8{
        .{ "content-type", "application/json" },
        .{ "content-encoding", "gzip" },
        .{ "authorization", authorization },
    };
    var authenticated = try requestWithRetry(&client, client_io.io(), .POST, url, "not gzip", &authenticated_headers, 20);
    defer authenticated.deinit();
    try std.testing.expectEqual(@as(u16, 400), authenticated.status.code);
    try std.testing.expectEqualStrings("invalid gzip request body", authenticated.body.?);
}

