/// Test metadata authority shared by direct and HTTP schema route regressions.
pub const SchemaUpdateStatusSource = struct {
    memory_logical_name: ?[]const u8 = null,
    table_name: []const u8 = "docs",
    projection_wait_calls: std.atomic.Value(u32) = .init(0),
    schema_json: ?[]const u8 = null,
    owns_schema_json: bool = false,
    dependency: ?metadata_table_manager.TableRecord = null,
    table_buf: [2]metadata_table_manager.TableRecord = undefined,
    range_buf: [1]metadata_table_manager.RangeRecord = undefined,

    pub fn iface(self: *@This()) http_server_mod.StatusSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .status = status,
                .admin_snapshot = adminSnapshot,
                .free_admin_snapshot = freeAdminSnapshot,
                .update_schema = updateSchema,
                .mutate_schema = mutateSchema,
                .wait_table_projection = waitTableProjection,
            },
        };
    }

    pub fn memoryIface(self: *@This()) http_server_mod.StatusSource {
        return .{ .ptr = self, .vtable = &.{ .status = status, .admin_snapshot = adminSnapshot, .free_admin_snapshot = freeAdminSnapshot, .system_catalog = memoryCatalog } };
    }
    fn memoryCatalog(ptr: *anyopaque, a: std.mem.Allocator, _: @import("antfly_local_sources").api_operation.RequestContext, call: @import("../system_catalog/server_call.zig").Call) ![]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const owned: system_catalog.ResolvedTable = .{ .table_id = 7, .name = self.table_name, .native_service = .memory };
        return switch (call) {
            .resolve => |target| std.json.Stringify.valueAlloc(a, @as(?system_catalog.ResolvedTable, if (std.mem.eql(u8, target.table, self.memory_logical_name orelse self.table_name)) owned else null), .{}),
            .resolve_many => |request| blk: {
                const tables = try a.alloc(?system_catalog.ResolvedTable, request.targets.len);
                defer a.free(tables);
                for (request.targets, tables) |target, *slot| slot.* = if (std.mem.eql(u8, target.table, self.memory_logical_name orelse self.table_name)) owned else null;
                const names = try a.alloc(?[]const u8, request.storage_names.len);
                defer a.free(names);
                for (request.storage_names, names) |name, *slot| slot.* = if (std.mem.eql(u8, name, self.table_name)) self.memory_logical_name orelse self.table_name else null;
                break :blk std.json.Stringify.valueAlloc(a, system_catalog.ResolvedMany{ .revision = 1, .tables = tables, .logical_names = names }, .{});
            },
            .query_definition => std.json.Stringify.valueAlloc(a, system_catalog.QueryDefinition{ .native_service = .memory, .table_id = 7, .schema_json = tables_api.default_schema_json, .read_schema_json = "", .indexes_json = tables_api.default_indexes_json }, .{}),
            .write_validation => std.json.Stringify.valueAlloc(a, .{ .schema_json = tables_api.default_schema_json, .data_shapes = &[_]struct {}{} }, .{}),
            .policy_publication_status => a.dupe(u8, "null"),
            else => error.UnsupportedOperation,
        };
    }

    pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        if (self.owns_schema_json) alloc.free(self.schema_json.?);
    }

    fn replaceSchemaJson(self: *@This(), alloc: std.mem.Allocator, next: []const u8) !void {
        if (self.owns_schema_json) alloc.free(self.schema_json.?);
        self.schema_json = try alloc.dupe(u8, next);
        self.owns_schema_json = true;
    }

    fn status(_: *anyopaque) !metadata_api.MetadataStatus {
        return .{
            .metadata_group_id = 1,
            .metrics = .{},
            .projected_stores = 1,
        };
    }

    fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        self.table_buf[0] = .{
            .table_id = 7,
            .name = self.table_name,
            .schema_json = tables_api.effectiveSchemaJson(self.schema_json),
            .indexes_json = tables_api.default_indexes_json,
            .placement_role = "data",
        };
        self.range_buf[0] = .{
            .group_id = 7001,
            .table_id = 7,
            .start_key = "",
            .end_key = null,
        };
        if (self.dependency) |table| self.table_buf[1] = table;
        return .{
            .status = .{ .metadata_group_id = 1, .metrics = .{} },
            .tables = self.table_buf[0..if (self.dependency != null) @as(usize, 2) else 1],
            .ranges = &self.range_buf,
            .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
            .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
            .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
            .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
        };
    }

    fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

    pub fn updateSchema(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        try std.testing.expectEqualStrings("docs", table_name);
        try self.replaceSchemaJson(alloc, schema_json);
    }

    fn mutateSchema(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        mode: tables_api.SchemaMutationMode,
        body: []const u8,
        expected_version: ?u32,
    ) !tables_api.SchemaMutationResult {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        try std.testing.expectEqualStrings("docs", table_name);
        const current = metadata_table_manager.TableRecord{
            .table_id = 7,
            .name = "docs",
            .schema_json = tables_api.effectiveSchemaJson(self.schema_json),
            .indexes_json = tables_api.default_indexes_json,
            .placement_role = "data",
        };
        if (expected_version) |expected| {
            if (try tables_api.schemaVersion(current.schema_json) != expected)
                return error.SchemaVersionChanged;
        }
        const updated = try tables_api.applySchemaMutationRecord(alloc, &current, mode, body);
        defer metadata_table_manager.freeTable(alloc, updated);
        try self.replaceSchemaJson(alloc, updated.schema_json);
        return .{
            .version = try tables_api.schemaVersion(updated.schema_json),
            .schema_json = try alloc.dupe(u8, updated.schema_json),
        };
    }

    fn waitTableProjection(ptr: *anyopaque, table_name: []const u8, schema_json: ?[]const u8, indexes_json: ?[]const u8) !void {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        try std.testing.expectEqualStrings("docs", table_name);
        try std.testing.expect(indexes_json != null);
        try std.testing.expect(schema_json != null);
        try std.testing.expect(self.schema_json != null);
        _ = self.projection_wait_calls.fetchAdd(1, .monotonic);
    }
};

const SchemaReconcileWriteSource = struct {
    reconcile_calls: std.atomic.Value(u32) = .init(0),
    synchronous_update_calls: std.atomic.Value(u32) = .init(0),

    fn iface(self: *@This()) table_writes.TableWriteSource {
