        } else {
            try std.testing.expect(response.headers.get(metadata_api.read_index_absence_header) == null);
        }
    }
}

test "online merge ingress bounds owner work using the transport clock" {
    const contract = @import("online_merge_io.zig").contract;
    var sim = try @import("vopr").vopr_io.VoprIo.init(.{});
    defer sim.deinit();
    for ([_][]const u8{ "250", "0", "5001", "invalid" }) |value| {
        var request = try httpx.Request.init(std.testing.allocator, .POST, "http://node/internal/v1/groups/7/tables/docs/online-merge-io");
        defer request.deinit();
        try request.setHeader(contract.remaining_ms_header, value);
        var ctx = httpx.Context.init(std.testing.allocator, sim.io(), &request);
        defer ctx.deinit();
        AntflyApiHandler.establishInternalOnlineMergeDeadline(&ctx);
        if (!std.mem.eql(u8, value, "250")) {
            try std.testing.expect(ctx.application_deadline_invalid);
            try std.testing.expect(ctx.application_deadline_ns == null);
            continue;
        }
        const control = AntflyApiHandler.operationContext(&ctx, null);
        try std.testing.expectEqual(@as(u64, 250 * std.time.ns_per_ms), control.deadline_ns.?);
        try control.ensureActive();
        sim.monotonic_ns = 250 * std.time.ns_per_ms;
        try std.testing.expectError(error.DeadlineExceeded, control.ensureActive());
        sim.monotonic_ns = 0;
        // An already-admitted shorter budget must survive middleware unchanged.
        ctx.application_deadline_ns = 100 * std.time.ns_per_ms;
        AntflyApiHandler.establishInternalOnlineMergeDeadline(&ctx);
        try std.testing.expectEqual(@as(?u64, 100 * std.time.ns_per_ms), ctx.application_deadline_ns);
        ctx.application_deadline_ns = 1000 * std.time.ns_per_ms;
        AntflyApiHandler.establishInternalOnlineMergeDeadline(&ctx);
        try std.testing.expectEqual(@as(?u64, 250 * std.time.ns_per_ms), ctx.application_deadline_ns);
    }
    var public_request = try httpx.Request.init(std.testing.allocator, .GET, "http://node/tables/docs");
    defer public_request.deinit();
    try public_request.setHeader(contract.remaining_ms_header, "250");
    var public_ctx = httpx.Context.init(std.testing.allocator, sim.io(), &public_request);
    defer public_ctx.deinit();
    AntflyApiHandler.establishInternalOnlineMergeDeadline(&public_ctx);
    try std.testing.expect(public_ctx.application_deadline_ns == null);
}

test "internal transaction ingress establishes and validates pre-decision deadline" {
    // Routed reads use the transport's clock even when the host epoch is
    // unrelated. Transaction-only ingress uses that same clock contract.
    {
        var sim = try @import("vopr").vopr_io.VoprIo.init(.{});
        defer sim.deinit();
        var routed_request = try httpx.Request.init(std.testing.allocator, .GET, "http://node/internal/v1/groups/7/tables/docs/lookup/doc");
        defer routed_request.deinit();
        try routed_request.setHeader(metadata_api.catalog_route_fence_header, "{}");
        try routed_request.setHeader(metadata_api.catalog_route_deadline_ms_header, "250");
        var routed_ctx = httpx.Context.init(std.testing.allocator, sim.io(), &routed_request);
        defer routed_ctx.deinit();
        AntflyApiHandler.establishCatalogRouteFenceDeadline(&routed_ctx);
        const operation = AntflyApiHandler.operationContext(&routed_ctx, null);
        try std.testing.expectEqual(@as(u64, 250 * std.time.ns_per_ms), operation.deadline_ns.?);
        try operation.ensureActive();
        const options = db_mod.types.LookupOptions{ .execution_deadline_ns = operation.deadline_ns, .execution_io = operation.deadline_io };
        try std.testing.expectEqual(@as(u64, 0), options.executionNowNs());
        sim.monotonic_ns = 250 * std.time.ns_per_ms;
        try std.testing.expectError(error.DeadlineExceeded, operation.ensureActive());
        try std.testing.expect(options.executionNowNs() >= options.execution_deadline_ns.?);
    }
    const budget_ms: u32 = 250;
    var request = try httpx.Request.init(
        std.testing.allocator,
        .POST,
        "http://127.0.0.1/internal/v1/groups/7/tables/docs/txn-begin",
    );
    defer request.deinit();
    try request.setHeader(distributed_txn_contract.pre_decision_remaining_ms_header, "250");
    var ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &request);
    defer ctx.deinit();
    const before_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, ctx.io).nanoseconds));
    AntflyApiHandler.establishInternalTxnPreDecisionDeadline(&ctx);
    const after_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, ctx.io).nanoseconds));
    const deadline_ns = ctx.application_deadline_ns.?;
    try std.testing.expect(deadline_ns >= before_ns + budget_ms * std.time.ns_per_ms);
    try std.testing.expect(deadline_ns <= after_ns + budget_ms * std.time.ns_per_ms);
    try std.testing.expectEqual(deadline_ns, AntflyApiHandler.operationContext(&ctx, null).deadline_ns.?);

    var invalid_request = try httpx.Request.init(
        std.testing.allocator,
        .POST,
        "http://127.0.0.1/internal/v1/groups/7/tables/docs/txn-prepare",
    );
    defer invalid_request.deinit();
    try invalid_request.setHeader(distributed_txn_contract.pre_decision_remaining_ms_header, "5001");
    var invalid_ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &invalid_request);
    defer invalid_ctx.deinit();
    AntflyApiHandler.establishInternalTxnPreDecisionDeadline(&invalid_ctx);
    try std.testing.expect(invalid_ctx.application_deadline_ns == null);
    try std.testing.expect(invalid_ctx.application_deadline_invalid);

    var status_request = try httpx.Request.init(
        std.testing.allocator,
        .POST,
        "http://127.0.0.1/internal/v1/groups/7/tables/docs/txn-status",
    );
    defer status_request.deinit();
    try status_request.setHeader(distributed_txn_contract.status_remaining_ms_header, "250");
    var status_ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &status_request);
    defer status_ctx.deinit();
    const status_before_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, status_ctx.io).nanoseconds));
    AntflyApiHandler.establishInternalTxnStatusDeadline(&status_ctx);
    const status_after_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, status_ctx.io).nanoseconds));
    const status_deadline_ns = status_ctx.application_deadline_ns.?;
    try std.testing.expect(status_deadline_ns >= status_before_ns + budget_ms * std.time.ns_per_ms);
    try std.testing.expect(status_deadline_ns <= status_after_ns + budget_ms * std.time.ns_per_ms);

    var invalid_status_request = try httpx.Request.init(
        std.testing.allocator,
        .POST,
        "http://127.0.0.1/internal/v1/groups/7/tables/docs/txn-status",
    );
    defer invalid_status_request.deinit();
    try invalid_status_request.setHeader(distributed_txn_contract.status_remaining_ms_header, "5001");
    var invalid_status_ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &invalid_status_request);
    defer invalid_status_ctx.deinit();
    AntflyApiHandler.establishInternalTxnStatusDeadline(&invalid_status_ctx);
    try std.testing.expect(invalid_status_ctx.application_deadline_ns == null);
    try std.testing.expect(invalid_status_ctx.application_deadline_invalid);

    var backup_request = try httpx.Request.init(
        std.testing.allocator,
        .POST,
        "http://127.0.0.1/internal/v1/groups/7/tables/docs/backup-shard",
    );
    defer backup_request.deinit();
    try backup_request.setHeader(backups_api.backup_remaining_ms_header, "250");
    var backup_ctx = httpx.Context.init(std.testing.allocator, std.testing.io, &backup_request);
    defer backup_ctx.deinit();
    const backup_before_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, backup_ctx.io).nanoseconds));
    AntflyApiHandler.establishInternalBackupDeadline(&backup_ctx);
    const backup_after_ns = @as(u64, @intCast(std.Io.Clock.now(.awake, backup_ctx.io).nanoseconds));
    const backup_deadline_ns = backup_ctx.application_deadline_ns.?;
    try std.testing.expect(backup_deadline_ns >= backup_before_ns + budget_ms * std.time.ns_per_ms);
    try std.testing.expect(backup_deadline_ns <= backup_after_ns + budget_ms * std.time.ns_per_ms);
}

test "HA mutation middleware fails closed for unregistered HTTP methods" {
    try std.testing.expect(AntflyApiHandler.classifyHotStandbyMutation(.GET, "/tables/docs") == null);
    try std.testing.expect(AntflyApiHandler.classifyHotStandbyMutation(.HEAD, "/tables/docs") == null);
    try std.testing.expect(AntflyApiHandler.classifyHotStandbyMutation(.OPTIONS, "/tables/docs") == null);

    const global_query = AntflyApiHandler.classifyHotStandbyMutation(.POST, routes.global_query).?;
    try std.testing.expectEqual(hot_standby_mutation_inventory.Surface.read_like_post, global_query.surface);
    try std.testing.expectEqual(hot_standby_mutation_inventory.Disposition.read_only, global_query.disposition);

    const unknown_query_suffix = AntflyApiHandler.classifyHotStandbyMutation(.POST, "/query/future-action").?;
    try std.testing.expectEqual(hot_standby_mutation_inventory.Surface.unclassified_non_get, unknown_query_suffix.surface);
    try std.testing.expectEqual(hot_standby_mutation_inventory.Disposition.reject, unknown_query_suffix.disposition);

    const patch = AntflyApiHandler.classifyHotStandbyMutation(.PATCH, "/tables/docs").?;
